const COMBINED_QUESTIONS = [{"id":"ml-1","sourceBank":"microsoft-learn","type":"single","question":"When designing a Dataverse solution, which approach should you evaluate FIRST before writing a plug-in?","options":["Always write a plug-in for any business logic","Whether a declarative option (business rule, calculated/rollup column, Power Automate, custom action) can meet the requirement","Whether to write the code in C# or JavaScript","Whether to use the Web API or the Organization service"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Out-of-the-box vs Custom Code","sub":null,"explanation":"Microsoft guidance is to first consider declarative options (business rules, calculated/rollup columns, Power Automate, custom actions) before writing a plug-in. Use plug-ins only when a declarative process can't meet the requirement.","source":{"title":"Use plug-ins to extend business processes","url":"https://learn.microsoft.com/power-apps/developer/data-platform/plug-ins"}},{"id":"ml-2","sourceBank":"microsoft-learn","type":"single","question":"A requirement must run server-side, synchronously, within the Dataverse database transaction, and be able to cancel an invalid operation. Which option fits best?","options":["Client-side JavaScript on the form","A synchronous Dataverse plug-in","A scheduled Power Automate cloud flow","A canvas app Power Fx formula"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Where to Implement Business Logic","sub":null,"explanation":"Server-side logic that runs inside the transaction and can cancel the operation is a synchronous plug-in. Client scripting runs only in the form; scheduled flows run later and out-of-transaction; canvas Power Fx is client-side.","source":{"title":"Use plug-ins to extend business processes","url":"https://learn.microsoft.com/power-apps/developer/data-platform/plug-ins"}},{"id":"ml-3","sourceBank":"microsoft-learn","type":"single","question":"Which business logic option executes in the user's browser and can react to form events like OnLoad and OnChange?","options":["A Dataverse plug-in","Client scripting (JavaScript using the Client API)","An Azure Function","A rollup column"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Client vs Server Logic","sub":null,"explanation":"Client scripting (JavaScript targeting the Client API object model) runs in the browser and reacts to model-driven form/grid events such as OnLoad, OnChange, and OnSave. Plug-ins and Azure Functions run server-side.","source":{"title":"Apply business logic using client scripting in model-driven apps","url":"https://learn.microsoft.com/power-apps/developer/model-driven-apps/client-scripting"}},{"id":"ml-4","sourceBank":"microsoft-learn","type":"single","question":"You need a Dataverse table that surfaces data living in an external system in real time, without copying it into Dataverse. Which table type fits?","options":["Standard table","Virtual table","Elastic table","Activity table"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Table Types","sub":null,"explanation":"A virtual table surfaces data from an external data source in real time as if it were a Dataverse table, without storing the data in Dataverse. Standard tables store data in Dataverse; elastic tables suit very high-volume/NoSQL-style workloads.","source":{"title":"Types of tables in Dataverse","url":"https://learn.microsoft.com/power-apps/maker/data-platform/types-of-entities"}},{"id":"ml-5","sourceBank":"microsoft-learn","type":"single","question":"Which Power Platform feature can BLOCK a custom connector or flow from combining data between connector groups, and so must be considered when designing integrations?","options":["Data loss prevention (DLP) policies","Solution layers","Environment variables","Alternate keys"],"correct":[0],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Security Feature Impact","sub":null,"explanation":"DLP policies classify connectors as business vs non-business and block data flowing between groups. When designing solution components that use connectors, you must assess DLP impact (alongside security roles, teams, business units, and row sharing).","source":{"title":"Data loss prevention policies (Power Platform)","url":"https://learn.microsoft.com/power-platform/admin/wp-data-loss-prevention"}},{"id":"ml-6","sourceBank":"microsoft-learn","type":"single","question":"Which authentication method does Microsoft recommend when designing a custom connector that secures access to your API?","options":["No authentication","Microsoft Entra ID (OAuth 2.0)","Hard-coded credentials in the connector","A shared password emailed to users"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Authentication Strategy","sub":null,"explanation":"For custom connectors, Microsoft recommends Microsoft Entra ID (OAuth 2.0). Custom connectors support generic OAuth 2.0, service-specific OAuth, Basic auth, and API key — but Entra ID is the recommended approach.","source":{"title":"Custom connectors overview (Secure your API)","url":"https://learn.microsoft.com/connectors/custom-connectors/"}},{"id":"ml-7","sourceBank":"microsoft-learn","type":"single","question":"You need a reusable UI control that renders a custom visual (e.g., a slider or map) bound to a column or dataset across model-driven and canvas apps. Which component type should you design?","options":["An HTML web resource","A Power Apps component framework (PCF) code component","A Power Automate child flow","A Dataverse business rule"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Designing Reusable Components","sub":null,"explanation":"PCF code components are reusable controls that render bound to columns or datasets across model-driven and canvas apps, loading in the same context as native controls (unlike HTML web resources). They're a core reusable-component design choice for developers.","source":{"title":"Power Apps component framework overview","url":"https://learn.microsoft.com/power-apps/developer/component-framework/overview"}},{"id":"ml-8","sourceBank":"microsoft-learn","type":"single","question":"When configuring Dataverse security so a plug-in or code component works while minimizing risk, which principle should you follow?","options":["Grant every user the System Administrator role","Grant the least privilege required — only the privileges the component needs","Disable security roles entirely","Use a single shared account with full access for all code"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Security Roles for Code (Least Privilege)","sub":null,"explanation":"Configure Dataverse security roles to support code components following the principle of least privilege — granting only the privileges the component needs, rather than over-permissioning users or using broad admin roles.","source":{"title":"Security roles and privileges (Power Platform)","url":"https://learn.microsoft.com/power-platform/admin/security-roles-privileges"}},{"id":"ml-9","sourceBank":"microsoft-learn","type":"single","question":"Following ALM best practice, where should developers make and test customizations before they reach production?","options":["Directly in the production environment","In a development (and separate test) environment, distributing changes downstream","Only in the default environment shared by all users","In an end user's personal OneDrive"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Development Environments","sub":null,"explanation":"Makers and developers work in development environments using unmanaged solutions, then import to downstream environments (test, UAT, production) as managed solutions — keeping experiments out of production.","source":{"title":"Solution concepts (ALM)","url":"https://learn.microsoft.com/power-platform/alm/solution-concepts-alm"}},{"id":"ml-10","sourceBank":"microsoft-learn","type":"single","question":"Which statement about managed and unmanaged solutions is correct?","options":["You develop in managed solutions and deploy unmanaged to production","You develop in unmanaged solutions (your source) and deploy managed solutions to downstream environments","Managed and unmanaged solutions are identical","You can freely edit components directly inside a managed solution"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Managed vs Unmanaged Solutions","sub":null,"explanation":"Unmanaged solutions are developed (and are your source, checked into source control); managed solutions are deployed to downstream environments (test/prod). You can't edit components directly within a managed solution.","source":{"title":"Solution concepts (ALM)","url":"https://learn.microsoft.com/power-platform/alm/solution-concepts-alm"}},{"id":"ml-11","sourceBank":"microsoft-learn","type":"single","question":"What happens when you delete (uninstall) a managed solution that contains a custom table?","options":["Nothing is removed; the components stay in the default solution","All the customizations and extensions it included are removed, and data in its custom tables/columns is lost","Only the solution container is removed but the table and its data remain","The solution is converted to unmanaged"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Deleting a Managed Solution","sub":null,"explanation":"Deleting a managed solution removes all the customizations and extensions it included; data stored in custom tables and custom columns that are part of the managed solution is lost. (Deleting an unmanaged solution removes only the container.)","source":{"title":"Solution concepts (ALM)","url":"https://learn.microsoft.com/power-platform/alm/solution-concepts-alm"}},{"id":"ml-12","sourceBank":"microsoft-learn","type":"single","question":"When you import an unmanaged solution's customizations in a dev environment and later import it as managed to test, which layers are involved?","options":["Customizing in dev works in the unmanaged layer; the managed solution imports into the managed layer","Both always use the managed layer","Layers don't exist in Power Platform","Unmanaged solutions have no layer at all"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Solution Layers","sub":null,"explanation":"When you customize in development you work in the unmanaged layer. When you export as managed and import to another environment, the managed solution is imported into the managed layer. Solution layers determine the runtime behavior when multiple solutions affect a component.","source":{"title":"Solution layers (ALM)","url":"https://learn.microsoft.com/power-platform/alm/solution-layers-alm"}},{"id":"ml-13","sourceBank":"microsoft-learn","type":"single","question":"What is the purpose of environment variables in a Power Platform solution?","options":["To store the GUID primary key of every row","To store configuration values that differ per environment (e.g., a URL or API key) so the same solution works across dev/test/prod without code changes","To define plug-in pipeline stages","To replace security roles"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Environment Variables","sub":null,"explanation":"Environment variables let you store configuration values (such as endpoints, IDs, or secrets via Key Vault references) that can differ between environments. The same solution can carry the variable definition and receive environment-specific values on import — supporting healthy ALM.","source":{"title":"Environment variables overview","url":"https://learn.microsoft.com/power-apps/maker/data-platform/environmentvariables"}},{"id":"ml-14","sourceBank":"microsoft-learn","type":"single","question":"Which tools support automated CI/CD deployment of Power Platform solutions across environments?","options":["Power Platform Pipelines and Power Platform Build Tools (Azure DevOps / GitHub)","Power BI Desktop and Excel","The Plug-in Registration Tool only","Azure Key Vault only"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Pipelines & Build Tools","sub":null,"explanation":"Power Platform Pipelines provide in-product automated deployment between environments, and Power Platform Build Tools enable CI/CD automations in Azure DevOps (and GitHub Actions) to export, import, and manage solutions.","source":{"title":"Microsoft Power Platform Build Tools for Azure DevOps","url":"https://learn.microsoft.com/power-platform/alm/devops-build-tools"}},{"id":"ml-15","sourceBank":"microsoft-learn","type":"single","question":"What is Power Fx?","options":["A C#-based server-side language for plug-ins","The low-code, Excel-like formula language used across Power Platform (e.g., canvas apps)","A REST protocol for Dataverse","A type of Dataverse table"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Power Fx","sub":null,"explanation":"Power Fx is the low-code, Excel-like formula language used across Power Platform. Developers implement complex formulas and functions (e.g., for filtering, lookups, and logic) in canvas apps and increasingly elsewhere.","source":{"title":"Power Fx overview","url":"https://learn.microsoft.com/power-platform/power-fx/overview"}},{"id":"ml-16","sourceBank":"microsoft-learn","type":"single","question":"How do you make a canvas app component reusable across multiple apps in an environment?","options":["Copy-paste the controls into each app manually","Publish it in a component library that apps can reference and update from","Convert it to a Dataverse table","Register it with the Plug-in Registration Tool"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Component Libraries","sub":null,"explanation":"Component libraries are containers of reusable canvas components that can be shared across apps. Apps reference the library and can pick up updates, avoiding copy-paste duplication.","source":{"title":"Component library (canvas apps)","url":"https://learn.microsoft.com/power-apps/maker/canvas-apps/component-library"}},{"id":"ml-17","sourceBank":"microsoft-learn","type":"single","question":"How can a canvas app run server-side business logic implemented in a Power Automate cloud flow?","options":["It cannot call flows","By adding the flow to the app and calling it (e.g., with the Power Automate connector / .Run) from a control's Power Fx","By registering the flow as a plug-in step","By embedding the flow as an HTML web resource"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Calling Flows from Canvas","sub":null,"explanation":"A canvas app can invoke a Power Automate cloud flow (instant trigger) — adding the flow to the app and calling it from a control's OnSelect with Power Fx — to implement business logic, pass parameters, and receive responses.","source":{"title":"Use logic flows from canvas apps","url":"https://learn.microsoft.com/power-apps/maker/canvas-apps/using-logic-flows"}},{"id":"ml-18","sourceBank":"microsoft-learn","type":"single","question":"Which tool lets you watch a live stream of events and diagnostics while a canvas or model-driven app runs, to troubleshoot issues?","options":["Monitor","Plug-in Registration Tool","Solution checker","Power Platform CLI only"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Monitor","sub":null,"explanation":"Monitor provides a live stream of events as an app runs, helping developers troubleshoot canvas and model-driven app issues (alongside browser-based debugging tools).","source":{"title":"Monitor overview","url":"https://learn.microsoft.com/power-apps/maker/monitor-overview"}},{"id":"ml-19","sourceBank":"microsoft-learn","type":"single","question":"A canvas app gallery only shows 500 of thousands of matching rows. What concept explains this and should guide your query design?","options":["Delegation — non-delegable operations only process the local record limit (default 500)","Solution layering","Plug-in pipeline stages","Alternate keys"],"correct":[0],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Delegation","sub":null,"explanation":"Delegation pushes query processing to the data source. When a function/operation isn't delegable, Power Apps only retrieves up to the local record limit (default 500). Designing delegable queries is key to canvas app performance over large data.","source":{"title":"Understand delegation in a canvas app","url":"https://learn.microsoft.com/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"ml-20","sourceBank":"microsoft-learn","type":"single","question":"Which technique improves canvas app startup/runtime performance?","options":["Loading all data only when each screen is opened, repeatedly","Pre-loading or caching data (e.g., into collections) and using delegable queries to reduce round-trips","Disabling delegation entirely","Adding more non-delegable filters"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Canvas Performance — Pre-loading","sub":null,"explanation":"Optimizing canvas performance includes pre-loading/caching data (e.g., into collections), minimizing calls, and using delegable queries so processing happens at the data source rather than pulling everything to the client.","source":{"title":"Understand delegation in a canvas app","url":"https://learn.microsoft.com/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"ml-21","sourceBank":"microsoft-learn","type":"single","question":"Which choice helps optimize model-driven app performance?","options":["Adding many unfiltered subgrids and columns to every form and view","Simplifying forms (fewer controls/tabs, load-on-demand) and keeping views focused with appropriate columns and filters","Disabling all security roles","Storing data in canvas collections only"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Model-driven Performance","sub":null,"explanation":"Model-driven performance is improved by streamlining forms (fewer heavy controls, tabs that load on demand) and keeping views focused (appropriate columns, filtered queries), reducing the data and rendering work per load.","source":{"title":"Optimize model-driven app form performance","url":"https://learn.microsoft.com/power-apps/maker/model-driven-apps/optimize-form-performance"}},{"id":"ml-22","sourceBank":"microsoft-learn","type":"single","question":"In model-driven app client scripting, which object model do you use to read/write form data and respond to events?","options":["The Organization service (IOrganizationService)","The Client API object model (e.g., formContext)","The Plug-in Registration Tool API","Power Fx only"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Client API Object Model","sub":null,"explanation":"Client scripting uses the Client API object model (such as formContext / executionContext) to interact with form objects and events — reacting when a form loads, a column changes, or data is saved.","source":{"title":"Apply business logic using client scripting in model-driven apps","url":"https://learn.microsoft.com/power-apps/developer/model-driven-apps/client-scripting"}},{"id":"ml-23","sourceBank":"microsoft-learn","type":"single","question":"How do you make JavaScript run on a model-driven form's OnLoad event?","options":["Register the script as a plug-in step","Add the JavaScript as a script (JScript) web resource and register the function as an event handler on the form's OnLoad event","Put the JavaScript in an environment variable","Deploy it as an Azure Function"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Script Web Resources & Events","sub":null,"explanation":"You attach JavaScript to form events by adding it as a script (JScript) web resource and registering the function as a handler for the event (OnLoad, OnChange, OnSave). Business rules are the no-code alternative for simpler logic.","source":{"title":"Apply business logic using client scripting in model-driven apps","url":"https://learn.microsoft.com/power-apps/developer/model-driven-apps/client-scripting"}},{"id":"ml-24","sourceBank":"microsoft-learn","type":"single","question":"From client-side JavaScript in a model-driven app, which object do you use to perform Dataverse data operations via the Web API?","options":["Xrm.WebApi","IOrganizationService","HttpClient in C#","Power Fx Patch()"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Xrm.WebApi from Client Script","sub":null,"explanation":"Model-driven apps provide the Xrm.WebApi object, which exposes methods to create, retrieve, update, and delete Dataverse data through the Web API from client-side JavaScript.","source":{"title":"Use the Microsoft Dataverse Web API (Xrm.WebApi)","url":"https://learn.microsoft.com/power-apps/developer/data-platform/webapi/overview"}},{"id":"ml-25","sourceBank":"microsoft-learn","type":"single","question":"Which statement about ribbon commands/buttons and navigation in model-driven apps is correct?","options":["Commands can only be defined in C# plug-ins","You can configure commands and buttons using Power Fx or JavaScript, and navigate to custom pages using the Client API (Xrm.Navigation)","Navigation to custom pages is not possible","Buttons can't run any logic"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Commands & Navigation","sub":null,"explanation":"Modern commands and buttons can be configured with Power Fx or JavaScript, and you can navigate to custom pages and dialogs using the Client API (e.g., Xrm.Navigation.navigateTo).","source":{"title":"Client scripting and the Client API reference","url":"https://learn.microsoft.com/power-apps/developer/model-driven-apps/client-scripting"}},{"id":"ml-26","sourceBank":"microsoft-learn","type":"single","question":"In a Power Apps component framework (PCF) project, what does the manifest (ControlManifest.Input.xml) define?","options":["The plug-in pipeline stage","The component's metadata — properties, data-set/field bindings, and feature usage (e.g., external-service-usage)","The Dataverse security roles","The solution publisher prefix only"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"PCF Manifest","sub":null,"explanation":"The PCF manifest declares the component's metadata: its properties, whether it binds to a field or a dataset, resources, and feature usage (for example, the external-service-usage node that marks a component premium).","source":{"title":"Power Apps component framework overview","url":"https://learn.microsoft.com/power-apps/developer/component-framework/overview"}},{"id":"ml-27","sourceBank":"microsoft-learn","type":"single","question":"Which method in a PCF code component is called by the framework when bound data or context changes and the component should re-render?","options":["init() only, once","updateView()","destroy() on every change","Execute()"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"PCF Lifecycle","sub":null,"explanation":"PCF components implement lifecycle methods: init (initialize), updateView (called when data/context changes so the component re-renders), getOutputs (return values to the host), and destroy (cleanup). updateView handles changes after initialization.","source":{"title":"Power Apps component framework overview","url":"https://learn.microsoft.com/power-apps/developer/component-framework/overview"}},{"id":"ml-28","sourceBank":"microsoft-learn","type":"single","question":"How is a PCF code component delivered to a Power Apps environment so makers can use it?","options":["Email the TypeScript file to makers","Bundle it into a solution package, then import the solution into the environment (Dataverse)","Register it with the Plug-in Registration Tool","Publish it as a Power Automate child flow"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"PCF Packaging & Features","sub":null,"explanation":"After building the component with the Power Platform CLI, you pack it into a solution (pac solution) and import that solution into the Dataverse environment so the component appears in the maker experience. PCF components can also use Device, Utility, and Web API features.","source":{"title":"Power Apps component framework — package and deploy","url":"https://learn.microsoft.com/power-platform/alm/component-framework"}},{"id":"ml-29","sourceBank":"microsoft-learn","type":"single","question":"You want plug-in logic to validate and cancel an invalid operation BEFORE the database transaction and before security checks. Which pipeline stage should you register on?","options":["PreValidation","PreOperation","MainOperation","PostOperation"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Event Pipeline Stages","sub":null,"explanation":"PreValidation occurs before the main operation and outside the database transaction (and before security checks) — the right place to validate and cancel an operation cheaply. Cancelling in PreOperation/PostOperation rolls back the transaction with performance impact.","source":{"title":"Event framework in Microsoft Dataverse","url":"https://learn.microsoft.com/power-apps/developer/data-platform/event-framework"}},{"id":"ml-30","sourceBank":"microsoft-learn","type":"single","question":"Where should you register a plug-in step that must run AFTER the main operation, and which execution mode lets it run outside the transaction via the async service?","options":["PreValidation, synchronous","PostOperation, asynchronous","MainOperation, synchronous","PreOperation, asynchronous"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"PostOperation & Async","sub":null,"explanation":"Logic that runs after the main operation registers on PostOperation. Within PostOperation you can register the step in asynchronous execution mode, so it runs after the operation completes via the asynchronous service (outside the transaction).","source":{"title":"Event framework in Microsoft Dataverse","url":"https://learn.microsoft.com/power-apps/developer/data-platform/event-framework"}},{"id":"ml-31","sourceBank":"microsoft-learn","type":"single","question":"A Dataverse plug-in class must implement which interface, and what does the platform pass to it at run time?","options":["IOrganizationService; a connection string","IPlugin (with an Execute method); contextual data via IPluginExecutionContext (through the service provider)","IServiceEndpointNotificationService; a webhook URL","IDisposable; a file handle"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"IPlugin & Execution Context","sub":null,"explanation":"Plug-in classes implement IPlugin, which exposes a single Execute method. At run time the platform passes contextual data about the operation; the plug-in obtains IPluginExecutionContext (and services like IOrganizationService) from the service provider.","source":{"title":"Use plug-ins to extend business processes","url":"https://learn.microsoft.com/power-apps/developer/data-platform/plug-ins"}},{"id":"ml-32","sourceBank":"microsoft-learn","type":"single","question":"On an Update plug-in, the Target only contains the columns that changed. How do you read the value of a column that was NOT changed in this update?","options":["Register a Pre Image containing that column and read it from the context's PreEntityImages","It's impossible to read unchanged values","Use a Post Image only, which always has every column","Query the Web API from PreValidation before security checks"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Pre/Post Images","sub":null,"explanation":"Register a Pre Image (snapshot before the operation) that includes the needed columns, then read it from the context's PreEntityImages. Post Images capture values after the operation. Images let plug-ins access attributes not present in the Target.","source":{"title":"Event framework — event context","url":"https://learn.microsoft.com/power-apps/developer/data-platform/event-framework"}},{"id":"ml-33","sourceBank":"microsoft-learn","type":"single","question":"Why must synchronous plug-ins execute and complete quickly?","options":["Because they run in the browser","Because the data operation waits for the plug-in to finish, directly affecting end-user perceived performance (and there's a hard time limit)","Because they can't access the Organization service","Because they only run overnight"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Synchronous vs Asynchronous","sub":null,"explanation":"A synchronous plug-in causes the data operation to wait until the plug-in finishes, so it affects end-user perceived performance and must complete quickly; plug-ins also have a hard time limit. Asynchronous execution is queued and runs after the operation.","source":{"title":"Use plug-ins to extend business processes","url":"https://learn.microsoft.com/power-apps/developer/data-platform/plug-ins"}},{"id":"ml-34","sourceBank":"microsoft-learn","type":"single","question":"Inside a plug-in, how do you perform additional Dataverse data operations (create/retrieve/update)?","options":["Use IOrganizationService obtained from the service provider (IOrganizationServiceFactory)","Open a direct SQL connection to the database","Use Xrm.WebApi (the client object)","Use Power Fx Patch()"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Organization Service in Plug-ins","sub":null,"explanation":"Plug-ins use the Organization service (IOrganizationService), obtained via IOrganizationServiceFactory from the service provider, to perform data operations server-side. Xrm.WebApi is a client-side object, not for plug-ins.","source":{"title":"Use the Dataverse Web API and Organization service","url":"https://learn.microsoft.com/power-apps/developer/data-platform/webapi/overview"}},{"id":"ml-35","sourceBank":"microsoft-learn","type":"single","question":"You want to define a reusable, named Dataverse operation (message) that runs your plug-in logic and can be called from Web API or other code. What should you create?","options":["A custom API (custom message) with a plug-in that implements its logic","A canvas component","An environment variable","A Power BI dataset"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Custom API & Registration","sub":null,"explanation":"A custom API defines a custom message (named operation) with parameters; you implement its logic in a plug-in registered on the custom API's MainOperation. It can then be called like any other message via the Web API or Organization service. Plug-in steps are configured with the Plug-in Registration Tool.","source":{"title":"Create and use custom APIs","url":"https://learn.microsoft.com/power-apps/developer/data-platform/custom-api"}},{"id":"ml-36","sourceBank":"microsoft-learn","type":"single","question":"What is a custom connector, fundamentally?","options":["A Dataverse plug-in","A wrapper around a REST API (described by an OpenAPI/Swagger definition or Postman collection) that lets Power Apps, Power Automate, and Copilot Studio call it","A type of canvas control","A solution layer"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5B","topic":"Custom Connector = REST Wrapper","sub":null,"explanation":"A custom connector is a wrapper around a REST (or SOAP, for Logic Apps) API. You describe the API with an OpenAPI definition or a Postman collection so Power Apps, Power Automate, Logic Apps, and Copilot Studio can communicate with it.","source":{"title":"Custom connectors overview","url":"https://learn.microsoft.com/connectors/custom-connectors/"}},{"id":"ml-37","sourceBank":"microsoft-learn","type":"single","question":"Which is a valid way to define a custom connector?","options":["Only by hand-writing C# code","From an OpenAPI definition, a Postman collection, or from scratch in the connector portal","Only from a Dataverse table","Only by exporting a Power BI report"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5B","topic":"Importing Definitions","sub":null,"explanation":"You can create a custom connector from an OpenAPI (Swagger) definition, from a Postman collection, or from scratch in the connector portal. You can also import definitions from existing APIs, Azure services, and GitHub.","source":{"title":"Custom connectors overview","url":"https://learn.microsoft.com/connectors/custom-connectors/"}},{"id":"ml-38","sourceBank":"microsoft-learn","type":"single","question":"Which Azure service is commonly used to build the backend REST API that a custom connector wraps, especially for serverless/event logic?","options":["Azure Functions","Azure Blob Storage","Azure Key Vault","Azure Virtual Network"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5B","topic":"Azure Functions for Connectors","sub":null,"explanation":"For public APIs you create and manage, Microsoft suggests Azure Functions (also Azure Web Apps / API Apps). An Azure Function is a common way to build the REST backend that a custom connector wraps. Policy templates can modify connector behavior at runtime.","source":{"title":"Custom connectors overview","url":"https://learn.microsoft.com/connectors/custom-connectors/"}},{"id":"ml-39","sourceBank":"microsoft-learn","type":"single","question":"Which standard does the Dataverse Web API implement, and which HTTP methods map to create/retrieve/update/delete?","options":["SOAP; only POST","OData v4 (RESTful); POST, GET, PATCH, DELETE","GraphQL; QUERY/MUTATE","gRPC; streaming only"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5C","topic":"Web API is OData v4","sub":null,"explanation":"The Dataverse Web API implements OData v4, a RESTful protocol. Create/retrieve/update/delete map to POST, GET, PATCH, and DELETE; named operations are exposed as OData functions and actions.","source":{"title":"Use the Microsoft Dataverse Web API","url":"https://learn.microsoft.com/power-apps/developer/data-platform/webapi/overview"}},{"id":"ml-40","sourceBank":"microsoft-learn","type":"single","question":"Which statement correctly contrasts the Web API and the Organization service?","options":["They are completely unrelated and use different data","The Web API is a RESTful experience for any language; the Organization service is the .NET SDK — both ultimately go through the same underlying message pipeline","Only the Web API can write data","The Organization service is deprecated"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5C","topic":"Web API vs Organization Service","sub":null,"explanation":"The Web API gives a RESTful, language-agnostic experience; the Organization service is the .NET SDK using messages/requests. The Web API exposes most Organization service messages as OData functions/actions, and both invoke the same underlying platform messages.","source":{"title":"Use the Microsoft Dataverse Web API","url":"https://learn.microsoft.com/power-apps/developer/data-platform/webapi/overview"}},{"id":"ml-41","sourceBank":"microsoft-learn","type":"single","question":"Your integration calls the Dataverse Web API at high volume and starts receiving HTTP 429 responses. What should your code do?","options":["Ignore the response and keep sending at the same rate","Honor the Retry-After header and implement a retry policy (back off), respecting service protection limits","Switch to SOAP to avoid limits","Disable authentication to speed up calls"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5C","topic":"Service Protection / Retry","sub":null,"explanation":"Dataverse enforces service protection API limits and returns HTTP 429 when exceeded. Implement API limit retry policies that honor the Retry-After header and back off; also optimize for concurrency, transactions, and bulk operations. Authenticate with OAuth.","source":{"title":"Service protection API limits","url":"https://learn.microsoft.com/power-apps/developer/data-platform/api-limits"}},{"id":"ml-42","sourceBank":"microsoft-learn","type":"single","question":"An Azure Function processes a long-running workload for a Power Platform solution and must call Dataverse securely without storing secrets. What should it use to authenticate?","options":["A managed identity","A hard-coded username and password","An anonymous connection","A shared API key in the source code"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5D","topic":"Azure Functions & Managed Identity","sub":null,"explanation":"Use a managed identity to authenticate the Azure Function to Power Platform/Dataverse, avoiding stored secrets. Azure Functions are well suited to long-running operations and scheduled/event-driven triggers for Power Platform solutions.","source":{"title":"Use managed identities with Dataverse","url":"https://learn.microsoft.com/power-platform/admin/managed-identity-overview"}},{"id":"ml-43","sourceBank":"microsoft-learn","type":"single","question":"Which cloud flow capability lets you run actions only when a previous action fails, so you can handle errors gracefully?","options":["Configure run-after settings (e.g., 'has failed'/'is skipped') on an action, or use Scope + run-after for try/catch","Delete the flow when an error occurs","Use a Pre Image","Register a plug-in step"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5D","topic":"Cloud Flow Error Handling","sub":null,"explanation":"In cloud flows you implement error handling by configuring an action's 'configure run after' to run on the previous step's failure/timeout/skip, often using Scopes to build try/catch/finally patterns. You can also set trigger conditions and retry policies.","source":{"title":"Error handling in Power Automate","url":"https://learn.microsoft.com/power-automate/guidance/coding-guidelines/error-handling"}},{"id":"ml-44","sourceBank":"microsoft-learn","type":"single","question":"Which pair of practices supports reuse and secret management in advanced cloud flows?","options":["Copying the same actions into every flow; hard-coding secrets","Using child flows for reusable logic; retrieving secrets from Azure Key Vault (and using Entra ID service principals for auth)","Disabling all connectors; emailing passwords","Storing secrets in flow comments"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5D","topic":"Child Flows & Secrets","sub":null,"explanation":"Develop reusable logic with child flows (called from a parent), retrieve secrets securely from Azure Key Vault rather than hard-coding them, and authenticate using Microsoft Entra ID service principals where appropriate.","source":{"title":"Create child flows in Power Automate","url":"https://learn.microsoft.com/power-automate/create-child-flows"}},{"id":"ml-45","sourceBank":"microsoft-learn","type":"single","question":"Which tool do developers use to register plug-ins, webhooks, and Azure integrations so they respond to Dataverse events?","options":["The Plug-in Registration Tool","Power BI Desktop","The canvas app studio","Azure Key Vault"],"correct":[0],"skill":6,"confidence":"high","set":null,"section":"6A","topic":"Publishing Dataverse Events","sub":null,"explanation":"The Plug-in Registration Tool registers plug-ins, Azure Service Bus/Event Hub integrations, virtual table data providers, and webhooks against event framework steps. Code can also publish events via IServiceEndpointNotificationService.","source":{"title":"Event framework in Microsoft Dataverse","url":"https://learn.microsoft.com/power-apps/developer/data-platform/event-framework"}},{"id":"ml-46","sourceBank":"microsoft-learn","type":"single","question":"When a Dataverse event is pushed to an Azure Service Bus endpoint or a webhook, what does the receiving endpoint get?","options":["Nothing — events can't leave Dataverse","A RemoteExecutionContext containing data about the operation","The full database backup","Only the row's GUID with no other data"],"correct":[1],"skill":6,"confidence":"high","set":null,"section":"6A","topic":"Remote Execution Context","sub":null,"explanation":"For Azure Service Bus, Azure Event Hubs, or a webhook, the data posted to the registered endpoint comes as a RemoteExecutionContext (which implements IExecutionContext), carrying contextual data about the operation that raised the event.","source":{"title":"Event framework in Microsoft Dataverse","url":"https://learn.microsoft.com/power-apps/developer/data-platform/event-framework"}},{"id":"ml-47","sourceBank":"microsoft-learn","type":"single","question":"Which destinations can Dataverse push events to for asynchronous integration with external systems?","options":["Only email","Webhooks, Azure Service Bus, and Azure Event Hubs","Only SharePoint lists","Only Power BI"],"correct":[1],"skill":6,"confidence":"high","set":null,"section":"6A","topic":"Service Endpoints","sub":null,"explanation":"Dataverse can publish events to service endpoints — webhooks (synchronous or async HTTP), Azure Service Bus, and Azure Event Hubs — enabling external systems to listen for and react to Dataverse data events.","source":{"title":"Azure integration with Microsoft Dataverse","url":"https://learn.microsoft.com/power-apps/developer/data-platform/azure-integration"}},{"id":"ml-48","sourceBank":"microsoft-learn","type":"single","question":"You need to periodically synchronize only the Dataverse rows that changed since your last sync to an external system, efficiently. Which feature should you use?","options":["Change tracking","A Pre Image","A solution layer","An environment variable"],"correct":[0],"skill":6,"confidence":"high","set":null,"section":"6B","topic":"Change Tracking","sub":null,"explanation":"Change tracking lets you efficiently synchronize data by retrieving only the records that were created, updated, or deleted since the last synchronization (using a token), instead of re-reading the whole table.","source":{"title":"Use change tracking to synchronize data with external systems","url":"https://learn.microsoft.com/power-apps/developer/data-platform/use-change-tracking-synchronize-data-external-systems"}},{"id":"ml-49","sourceBank":"microsoft-learn","type":"single","question":"When importing records from an external system that has its own unique IDs (but not Dataverse GUIDs), which combination lets you insert-or-update without first querying for existence?","options":["Define an alternate key on the external ID and use the UpsertRequest message","Always use the GUID primary key and a Retrieve before each write","Use a Pre Image","Use a canvas component"],"correct":[0],"skill":6,"confidence":"high","set":null,"section":"6B","topic":"Alternate Keys & Upsert","sub":null,"explanation":"Define an alternate key based on the external system's unique value so you can reference rows by that business key, then use UpsertRequest, which creates the row if it doesn't exist or updates it if it does — ideal for data synchronization.","source":{"title":"Use an alternate key to reference a record","url":"https://learn.microsoft.com/power-apps/developer/data-platform/use-alternate-key-reference-record"}},{"id":"ml-50","sourceBank":"microsoft-learn","type":"single","question":"What is the main benefit of using UpsertRequest during data integration?","options":["It deletes all existing rows first","It avoids a separate existence check and race conditions by creating or updating in a single operation keyed on an alternate (or primary) key","It only works with the Web API and never the SDK","It bypasses security roles"],"correct":[1],"skill":6,"confidence":"high","set":null,"section":"6B","topic":"Why Upsert","sub":null,"explanation":"UpsertRequest performs a create-or-update in one operation based on a key (often an alternate key), removing the need for a separate retrieve-then-decide step and reducing round-trips and race conditions when syncing external data.","source":{"title":"Use an alternate key to reference a record","url":"https://learn.microsoft.com/power-apps/developer/data-platform/use-alternate-key-reference-record"}},{"id":"ml-101","sourceBank":"microsoft-learn","type":"single","question":"Which statement reflects Microsoft guidance on choosing plug-ins for custom logic?","options":["Always prefer plug-ins for everything","Plug-ins are powerful and performant but require developer skills and have a hard time limit, so weigh them against declarative options","Plug-ins can't connect to external systems","Plug-ins run only in the browser"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Plug-ins vs Workflow Activities","sub":null,"explanation":"Plug-ins are powerful and performant and can connect to external systems, but they require developer skills to build/maintain, can be abused (perf impact), and have a hard time limit. Evaluate declarative options first.","source":{"title":"Use plug-ins to extend business processes","url":"https://learn.microsoft.com/power-apps/developer/data-platform/plug-ins"}},{"id":"ml-102","sourceBank":"microsoft-learn","type":"single","question":"Which Dataverse table type is designed for very large volumes of data with high-throughput, flexible-schema (NoSQL-style) workloads?","options":["Standard table","Elastic table","Virtual table","Activity table"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Elastic Tables","sub":null,"explanation":"Elastic tables are built for scenarios needing massive scale and high throughput with a flexible schema (backed by Azure Cosmos DB). Standard tables are the default relational store; virtual tables surface external data.","source":{"title":"Types of tables in Dataverse","url":"https://learn.microsoft.com/power-apps/maker/data-platform/types-of-entities"}},{"id":"ml-103","sourceBank":"microsoft-learn","type":"single","question":"You need to change a component that arrived in a managed solution. What must you do, and what is the side effect?","options":["Edit it directly in the managed solution with no consequences","Add it to an unmanaged solution to edit it, which creates a dependency that prevents uninstalling the managed solution until removed","Delete the environment","Convert the managed solution to unmanaged"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Editing Managed Components","sub":null,"explanation":"You can't edit managed components directly; you add them to an unmanaged solution to edit. Doing so creates a dependency between your unmanaged customizations and the managed solution, which then can't be uninstalled until the dependency is removed.","source":{"title":"Solution concepts (ALM)","url":"https://learn.microsoft.com/power-platform/alm/solution-concepts-alm"}},{"id":"ml-104","sourceBank":"microsoft-learn","type":"single","question":"Why should you define a custom solution publisher with a meaningful prefix instead of using the default?","options":["The prefix changes the GUID of every row","The publisher prefix helps avoid naming collisions so solutions from different publishers can coexist; it should be set before creating components","It disables managed solutions","It is required to run plug-ins"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Solution Publisher Prefix","sub":null,"explanation":"The publisher prefix (e.g., contoso_) avoids naming collisions so solutions from different publishers can be installed in the same environment. Set it before creating metadata, because you can't rename metadata items afterward.","source":{"title":"Solution concepts (ALM)","url":"https://learn.microsoft.com/power-platform/alm/solution-concepts-alm"}},{"id":"ml-105","sourceBank":"microsoft-learn","type":"single","question":"Which approach keeps a canvas app accurate over a large data source?","options":["Rely on non-delegable functions and accept the 500-row limit","Use delegable functions/operators so filtering and sorting happen at the data source instead of pulling rows to the client","Load the entire table into a collection on every keystroke","Turn off the data row limit warning"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Delegable vs Non-delegable","sub":null,"explanation":"Use delegable functions and operators so the data source performs filtering/sorting and returns only needed rows. Non-delegable operations only process up to the local record limit (default 500), risking incorrect results over large data.","source":{"title":"Understand delegation in a canvas app","url":"https://learn.microsoft.com/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"ml-106","sourceBank":"microsoft-learn","type":"single","question":"When a canvas app calls a Power Automate cloud flow, how does it pass values and receive a result?","options":["It can't pass any values","It passes parameters in the .Run() call and can receive a response returned by the flow","Only through a Dataverse plug-in","Only by email"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Passing Data to a Flow","sub":null,"explanation":"An instant cloud flow added to a canvas app is called (e.g., FlowName.Run(arg1, arg2)) passing parameters from the app; the flow can return values via a Respond to Power Apps action that the app consumes.","source":{"title":"Use logic flows from canvas apps","url":"https://learn.microsoft.com/power-apps/maker/canvas-apps/using-logic-flows"}},{"id":"ml-107","sourceBank":"microsoft-learn","type":"single","question":"For simple form logic that a non-developer can maintain, what does Microsoft recommend before client scripting?","options":["Always write JavaScript","Use business rules — a no-code way to apply form logic — and use client scripting only when business rules can't meet the requirement","Use a plug-in for all form logic","Use an Azure Function for form logic"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Business Rules vs JavaScript","sub":null,"explanation":"Microsoft recommends business rules (no-code) for form logic where possible, since a non-developer can maintain them. Use client scripting (JavaScript + Client API) when the requirement can't be met with a business rule.","source":{"title":"Apply business logic using client scripting in model-driven apps","url":"https://learn.microsoft.com/power-apps/developer/model-driven-apps/client-scripting"}},{"id":"ml-108","sourceBank":"microsoft-learn","type":"single","question":"How do PCF code components differ from HTML web resources?","options":["PCF components load in a separate iframe after everything else","PCF components render in the same context and load with other components, and have access to framework APIs (lifecycle, data, Web API, device features)","Web resources are always faster and more capable","PCF components can't be reused"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"PCF vs HTML Web Resources","sub":null,"explanation":"Unlike HTML web resources, PCF code components render as part of the same context and load at the same time as other components, giving a seamless experience, plus access to framework APIs (lifecycle, contextual data, Web API, device/utility features) and reusability.","source":{"title":"Power Apps component framework overview","url":"https://learn.microsoft.com/power-apps/developer/component-framework/overview"}},{"id":"ml-109","sourceBank":"microsoft-learn","type":"single","question":"How do you declare that a PCF component connects to an external service (making it a premium component)?","options":["Add an external-service-usage node listing the domains to the component manifest","Email Microsoft support","Set a flag in the Plug-in Registration Tool","Add an environment variable"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"Declaring a PCF Component Premium","sub":null,"explanation":"You declare a code component as premium by adding an <external-service-usage enabled=\"true\"> node with the external domains it connects to in the component's manifest. Components that connect to external data through the browser are premium.","source":{"title":"Power Apps component framework overview (Licensing)","url":"https://learn.microsoft.com/power-apps/developer/component-framework/overview"}},{"id":"ml-110","sourceBank":"microsoft-learn","type":"single","question":"Where should a plug-in modify column values of the record being created/updated so the change is saved within the same transaction without triggering another event?","options":["PreOperation stage (modify the Target before the main operation)","PreValidation only, after security checks","PostOperation by updating the same record again","Client-side JavaScript"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"PreOperation Changes","sub":null,"explanation":"Change values in the PreOperation stage (within the transaction, before the main operation) by modifying the Target. Avoid changing the same record in PostOperation, which triggers a new Update event.","source":{"title":"Event framework in Microsoft Dataverse","url":"https://learn.microsoft.com/power-apps/developer/data-platform/event-framework"}},{"id":"ml-111","sourceBank":"microsoft-learn","type":"single","question":"How should a plug-in cancel an invalid operation and show a message to the user?","options":["Call Environment.Exit()","Throw an InvalidPluginExecutionException with an appropriate message (ideally detected in PreValidation)","Return null from Execute","Delete the record"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5A","topic":"Cancelling an Operation","sub":null,"explanation":"To cancel an operation, throw an InvalidPluginExecutionException with a descriptive message; detect the condition in PreValidation to avoid a costly transaction rollback. Any exception in a synchronous in-transaction stage rolls back the whole transaction.","source":{"title":"Event framework in Microsoft Dataverse","url":"https://learn.microsoft.com/power-apps/developer/data-platform/event-framework"}},{"id":"ml-112","sourceBank":"microsoft-learn","type":"single","question":"In the Dataverse Web API (OData v4), how are most Organization service messages exposed?","options":["As SQL stored procedures","As OData functions (typically GET, no side effects) and actions (typically POST, may have side effects)","They are not exposed at all","Only as GraphQL resolvers"],"correct":[1],"skill":5,"confidence":"high","set":null,"section":"5C","topic":"Functions vs Actions","sub":null,"explanation":"OData v4 provides named operations via functions and actions. The Web API exposes most Organization service messages as corresponding functions (usually GET) or actions (usually POST). CRUD operations use the standard HTTP verbs instead.","source":{"title":"Use the Microsoft Dataverse Web API","url":"https://learn.microsoft.com/power-apps/developer/data-platform/webapi/overview"}},{"id":"ml-113","sourceBank":"microsoft-learn","type":"single","question":"What do custom connector policy templates let you do?","options":["Modify connector behavior at runtime (e.g., route, set headers, convert values) without changing the backend API","Define Dataverse security roles","Create solution layers","Replace OAuth with no authentication"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5B","topic":"Policy Templates","sub":null,"explanation":"Policy templates let you change a custom connector's behavior at runtime — for example setting a header, routing a request, or transforming a value — without modifying the underlying API. You can also write code to transform data.","source":{"title":"Custom connectors overview","url":"https://learn.microsoft.com/connectors/custom-connectors/"}},{"id":"ml-114","sourceBank":"microsoft-learn","type":"single","question":"How can you stop a cloud flow from running its actions unless incoming data meets a condition, without starting the run at all?","options":["Add a trigger condition (filter) so the flow only triggers when the expression is true","Delete the trigger","Use a Pre Image","Register the flow as a plug-in"],"correct":[0],"skill":5,"confidence":"high","set":null,"section":"5D","topic":"Trigger Conditions","sub":null,"explanation":"A trigger condition (filter) evaluates an expression and only starts the flow when it's true, avoiding unnecessary runs. You can also configure retry policies on actions to handle transient failures.","source":{"title":"Error handling and trigger conditions in Power Automate","url":"https://learn.microsoft.com/power-automate/guidance/coding-guidelines/error-handling"}},{"id":"ml-115","sourceBank":"microsoft-learn","type":"single","question":"Which Dataverse integration option lets an external endpoint run synchronously (in the transaction) and even affect the operation?","options":["A webhook (which can be registered synchronously)","Azure Event Hubs (always async, telemetry-scale)","Change tracking","An alternate key"],"correct":[0],"skill":6,"confidence":"high","set":null,"section":"6A","topic":"Synchronous vs Async Endpoints","sub":null,"explanation":"Webhooks can be registered to run synchronously within the pipeline (and can affect the operation), whereas Azure Service Bus and Azure Event Hubs are asynchronous, fire-and-forget style integrations suited to decoupled/high-volume scenarios.","source":{"title":"Azure integration with Microsoft Dataverse","url":"https://learn.microsoft.com/power-apps/developer/data-platform/azure-integration"}},{"id":"ml-116","sourceBank":"microsoft-learn","type":"single","question":"How does change tracking let a sync job retrieve only what changed since last time?","options":["It returns a token; on the next sync you pass the token to get only the changes since then","It deletes all rows after each sync","It requires reading the entire table each time","It only works with canvas apps"],"correct":[0],"skill":6,"confidence":"high","set":null,"section":"6B","topic":"Change Tracking Tokens","sub":null,"explanation":"Change tracking returns a token representing the point of the last synchronization. On the next run you supply that token to retrieve only the rows created, updated, or deleted since then — efficient incremental sync to external systems.","source":{"title":"Use change tracking to synchronize data with external systems","url":"https://learn.microsoft.com/power-apps/developer/data-platform/use-change-tracking-synchronize-data-external-systems"}},{"id":"gen-1","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer must enforce that an opportunity's Estimated Close Date is never earlier than the Created On date. The rule must run on both the model-driven form and when records are created through the Web API, and it must not require deploying compiled code. Which implementation approach best fits these requirements?","options":["A business rule scoped to the table (all forms), which validates on the client and on the server","A JavaScript OnSave client script registered on the main form only","A canvas app formula using the Patch function with validation logic","A scheduled Power Automate cloud flow that corrects invalid rows nightly"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A business rule set to the table scope (Entity) runs both on forms and server-side for API operations without any compiled code, while client scripts run only on the form where registered.","source":{"title":"Apply business logic in Microsoft Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/processes"}},{"id":"gen-2","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An architect needs synchronous, transactional business logic that runs on the Dataverse server for every create of an account regardless of whether the call comes from a model-driven app, a custom connector, or the Web API. Which option is the most appropriate?","options":["A business rule scoped to a single form","A real-time (synchronous) workflow or plug-in registered on the Create message","A client-side OnLoad script","A recurring (scheduled) cloud flow"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Server-side logic that must run for all entry points and participate in the database transaction is implemented with real-time workflows or plug-ins on the message pipeline, not with form-bound rules/scripts or scheduled flows.","source":{"title":"Apply business logic in Microsoft Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/processes"}},{"id":"gen-3","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants low-code automation that reacts when a Dataverse row is created and then sends an approval and posts to Microsoft Teams, without writing code. Which Dataverse business-logic option should they choose?","options":["A business rule","A plug-in registered in the pre-operation stage","A Power Automate cloud flow using the Dataverse connector trigger","A calculated column"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Automate cloud flows are the recommended low-code way to run multi-step automation and integrate with services like Teams in response to Dataverse row events.","source":{"title":"Apply business logic in Microsoft Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/processes"}},{"id":"gen-4","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement about business rules in Dataverse is correct when deciding where to place validation logic?","options":["Business rules can call external REST APIs directly during evaluation","Business rules can only ever run on the client and never on the server","Business rules set to the table scope run when the form loads and also server-side, giving broader coverage than form-scoped rules","Business rules require Visual Studio and a compiled assembly to deploy"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Business rules are a no-code option; setting the scope to the whole table (Entity) makes them apply across forms and on the server, whereas a specific-form scope limits them to that form.","source":{"title":"Apply business logic in Microsoft Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/processes"}},{"id":"gen-5","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization needs to surface read-only inventory data that physically lives in an external SQL system inside a model-driven app, always showing the latest values without copying or storing the data in Dataverse. Which table type should the architect design for?","options":["A standard (user-owned) table","An activity table","A virtual table","An elastic table"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Virtual tables integrate external data at runtime so it appears as Dataverse rows without being stored in Dataverse, ideal for surfacing live external data.","source":{"title":"Types of tables — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/types-of-entities"}},{"id":"gen-6","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which characteristic distinguishes an activity table from a standard table in Dataverse?","options":["Activity tables represent an action with a time dimension, such as tasks, emails, or phone calls, and appear in activity feeds and timelines","Activity tables can never be owned by a user or team","Activity tables are always stored in Azure Cosmos DB","Activity tables cannot participate in relationships"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Activity tables are a special kind of table used to track actions that have a time dimension (such as tasks, emails, appointments) and integrate with timelines and activity feeds.","source":{"title":"Types of tables — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/types-of-entities"}},{"id":"gen-7","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When choosing table ownership during technical design, which ownership type enables row-level security so records can be assigned to and secured for individual users or teams?","options":["User- or team-owned","Organization-owned","Virtual-owned","Elastic-owned"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"User- or team-owned tables support ownership at the row level, enabling security based on the owning user or team; organization-owned rows are accessible organization-wide without per-row ownership.","source":{"title":"Types of tables — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/types-of-entities"}},{"id":"gen-8","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer is designing a virtual table over a third-party REST service. Which statement about virtual tables should shape the design?","options":["Virtual table data is copied into Dataverse on a nightly schedule","Virtual tables always support Dataverse auditing and change tracking natively","Virtual tables require the external data to be stored in Cosmos DB","Virtual tables use a data provider to read external data at runtime; support for create/update/delete and features like auditing depend on the provider"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Virtual tables rely on a data provider to map and retrieve external data at runtime; write support and certain Dataverse features are subject to provider limitations, so these constraints must be evaluated in design.","source":{"title":"Get started with virtual tables — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/virtual-entities/get-started-ve"}},{"id":"gen-9","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which limitation of virtual tables is most important to confirm before committing to them for a solution?","options":["Virtual tables can only be created with the Plug-in Registration Tool","Virtual columns can be of any type and always support calculated and rollup columns","Certain capabilities are not supported for virtual tables, such as some column types, auditing, and offline availability, depending on the data provider","Virtual tables are limited to a maximum of 5,000 rows total"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Virtual tables have documented limitations — including unsupported column types, auditing, and mobile offline — that vary by provider and must be validated against requirements.","source":{"title":"Get started with virtual tables — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/virtual-entities/get-started-ve"}},{"id":"gen-10","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A solution must ingest millions of high-volume IoT telemetry rows with unpredictable spikes, requiring automatic horizontal scaling and very fast writes rather than complex cross-table transactions. Which Dataverse table type is designed for this scenario?","options":["Standard table","Activity table","Virtual table","Elastic table"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Elastic tables are built on Azure Cosmos DB and are designed for very large, high-throughput, and highly variable workloads that need automatic horizontal scaling.","source":{"title":"Elastic tables for developers — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/elastic-tables"}},{"id":"gen-11","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When designing an elastic table, why is choosing an appropriate partition key important?","options":["The partition key governs how data is distributed and grouped for scalable, efficient queries and affects performance","The partition key determines the security role required to read rows","The partition key is only used to sort rows alphabetically in views","The partition key enables offline synchronization for mobile apps"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Elastic tables use a partition key (backed by Cosmos DB) to distribute and group data; querying within a single partition is efficient, so the key choice directly affects scalability and performance.","source":{"title":"Elastic tables for developers — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/elastic-tables"}},{"id":"gen-12","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An architect is comparing elastic tables and standard tables. Which statement is accurate for design decisions?","options":["Elastic tables support multi-table ACID transactions across many rows the same way standard tables do","Elastic tables cannot be created or queried through the Dataverse Web API","Standard tables cannot enforce security roles or business units","Standard tables should be used when you need relational features and multi-record transactions, while elastic tables suit massive, sparse, or highly variable data with fast single-row operations"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Standard tables are the right choice for relational and transactional needs; elastic tables trade some relational/transactional capabilities for scale and throughput on large, variable datasets.","source":{"title":"Elastic tables for developers — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/elastic-tables"}},{"id":"gen-13","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Dataverse security design, what does the access level of a privilege in a security role control?","options":["Which Azure region the environment is hosted in","The depth of access — for example User, Business Unit, Parent: Child Business Unit, or Organization — over which the user can perform the operation","Whether a plug-in runs synchronously or asynchronously","The maximum number of API calls allowed per day"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A privilege's access level defines the depth (scope) of access — user/basic, business unit (local), parent-child business unit (deep), or organization (global) — for that operation.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-14","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A requirement states that sales reps should only read and edit account rows owned within their own business unit, while regional managers can access rows across child business units. Which Dataverse security feature primarily satisfies this design?","options":["Data loss prevention (DLP) policies","Column-level (field) security profiles only","Security roles whose privileges use business-unit-based access levels","Environment variables"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Business units combined with security roles whose privileges are set to Business Unit or Parent: Child Business Unit access levels control how far a user's access extends across the org hierarchy.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-15","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"During design, an architect needs a specific set of users from different business units to collaborate on a shared set of records. Which approach aligns with Dataverse security concepts?","options":["Grant every user the System Administrator role","Disable security roles for the environment","Store the records in a virtual table to bypass privileges","Use a team (owner or Microsoft Entra group team) with a security role, and/or share individual records with the team"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Teams let users across business units be granted a role and own or be shared records, enabling cross-unit collaboration without over-privileging individuals.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-16","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which principle should guide how privileges are assigned to application users (service principals) that run integration code against Dataverse?","options":["Assign the broadest possible role so the code never fails on a permission error","Follow least privilege — grant a custom security role containing only the privileges and access levels the code actually needs","Application users do not require any security role in Dataverse","Privileges for application users are inherited automatically from the Global Administrator"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Least-privilege design means assigning application (service) users a tailored security role that contains only the privileges and access depth required, reducing risk.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-17","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A governance team must prevent makers from combining a business-data connector with a social-media connector in the same app or flow. Which Power Platform feature enforces this at the connector level?","options":["Security roles and privileges","A data loss prevention (DLP) / data policy that classifies connectors into Business, Non-Business, and Blocked groups","Environment variables","Field-level security profiles"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"DLP (data) policies classify connectors into groups; connectors in different groups cannot be used together in the same app or flow, which enforces the required separation.","source":{"title":"Data loss prevention policies — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/wp-data-loss-prevention"}},{"id":"gen-18","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"How does a data loss prevention (DLP) policy affect an existing flow when an administrator later moves one of its connectors into the Blocked group?","options":["The flow continues to run normally because DLP only applies at design time to new flows","The flow is deleted automatically from the environment","The flow is suspended/blocked from running because it now violates the policy until it is brought into compliance","The connector is automatically re-created as a custom connector to bypass the policy"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"DLP policies apply to existing resources too; when a flow or app violates a policy (for example a connector becomes blocked or crosses groups), it is prevented from running until it complies.","source":{"title":"Data loss prevention policies — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/wp-data-loss-prevention"}},{"id":"gen-19","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker builds a rating control on one screen of a canvas app using a group of shapes and an input, then discovers three other screens need the identical control with the same behavior. What is the most appropriate reusable solution component to design?","options":["A PCF code component authored in TypeScript","A canvas component with custom input and output properties","A separate canvas app embedded as an iframe","A model-driven form web resource"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Canvas components let makers build reusable low-code building blocks with custom input/output properties that can be reused across screens (and via component libraries across apps) without writing pro-code.","source":{"title":"Canvas component overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-component"}},{"id":"gen-20","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You are designing a canvas component that must send a selected value back to the screen that hosts it so a gallery can filter on it. Which custom property type should you define on the component to expose that value to the host app?","options":["An input property, because the host pushes data into the component","A data property bound to a Dataverse table","A behavior property that runs an OnSelect formula","An output property, because the component surfaces a value to the host"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Output custom properties expose a value produced inside the canvas component so the host app's formulas can read it; input properties flow data the other direction, from host into the component.","source":{"title":"Canvas component overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-component"}},{"id":"gen-21","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants a single set of canvas components maintained centrally and consumed across many different canvas apps, with the ability to publish updates that app makers can pull in. Which design approach fits this requirement?","options":["Copy and paste the components into each app individually","Store the components in a component library that apps reference","Convert each component into a separate custom connector","Recreate the components as environment variables"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A component library is the reuse mechanism for sharing canvas components across multiple apps; makers reference the library and can take published updates, unlike copy-paste which creates unmanaged duplicates.","source":{"title":"Canvas component overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-component"}},{"id":"gen-22","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A solution requires a custom slider-style visual with pixel-perfect rendering and rich interactivity that must work in BOTH model-driven apps and canvas apps, authored by a professional developer. Which component type should you design?","options":["A canvas component packaged in a component library","A classic HTML web resource","A Power Apps component framework (PCF) code component","A business rule"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"PCF code components are the pro-developer framework for building reusable UI components that run in both model-driven and canvas apps, giving full control over rendering and behavior.","source":{"title":"Power Apps component framework overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/overview"}},{"id":"gen-23","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your organization wants pro developers to replace default fields and datasets in model-driven apps with fully custom controls that use modern web technologies and can call the Dataverse Web API. Which technology is designed for this?","options":["Power Apps component framework (PCF)","Canvas components","Cloud flows","Business rules"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Power Apps component framework empowers professional developers to create code components that can replace standard fields and datasets, built with web standards and able to use framework features such as the Web API.","source":{"title":"Power Apps component framework overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/overview"}},{"id":"gen-24","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer compares canvas components with PCF code components for a new reusable control. Which statement best reflects the intended design distinction between them?","options":["Canvas components require TypeScript and the pac CLI, while PCF is a no-code feature","PCF code components are for professional developers using code, while canvas components are low-code and built with Power Fx","Canvas components can only be used in model-driven apps","PCF components cannot be added to solutions for ALM"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Canvas components are a low-code reuse feature built with Power Fx, whereas PCF code components target professional developers who write code for advanced, reusable controls across app types.","source":{"title":"Power Apps component framework overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/overview"}},{"id":"gen-25","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An integration design must let makers call an existing internal REST API from both a Power Automate cloud flow and a canvas app, presenting its operations as friendly triggers and actions. Which component should you design and build?","options":["A Dataverse plug-in registered on the message pipeline","A PCF code component","An environment variable pointing to the API URL","A custom connector that wraps the REST API"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A custom connector is a wrapper around a REST API that lets Power Automate, Power Apps, and Logic Apps communicate with that service through defined triggers and actions.","source":{"title":"Custom connectors overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/"}},{"id":"gen-26","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"While designing a custom connector for a third-party API, you must decide how the connector authenticates to the service. Which of the following is a supported authentication type you would configure on a custom connector?","options":["Windows NTLM pass-through only","Kerberos delegation only","SQL integrated security","OAuth 2.0"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Custom connectors support authentication types such as OAuth 2.0, API key, and basic authentication so the wrapped REST API can be secured appropriately.","source":{"title":"Custom connectors overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/"}},{"id":"gen-27","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After building a custom connector for your team, you want it to be broadly available to other organizations and listed as an out-of-the-box connector. Which lifecycle step is designed for that outcome?","options":["Sharing the connector within your environment only","Exporting the connector as a solution ZIP","Submitting the connector for Microsoft certification","Converting the connector into a PCF component"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Certifying a custom connector through Microsoft's certification process is how it becomes publicly available to all users as a shipped connector, beyond simple sharing within a tenant.","source":{"title":"Custom connectors overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/"}},{"id":"gen-28","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer needs to expose a reusable, code-first operation in Dataverse that encapsulates complex server-side logic and can be invoked as its own message from plug-ins, the Web API, and the Organization service. Which component should be designed?","options":["A canvas component","A classic workflow","An alternate key","A custom API (custom message)"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A custom API defines a code-first custom message in Dataverse that packages logic behind a single callable operation, invokable from the Web API, Organization service, and plug-ins.","source":{"title":"Create and use custom APIs — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/custom-api"}},{"id":"gen-29","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You are designing a custom API in Dataverse that must accept an account record reference and a text value as inputs and return a computed number. How are these inputs and outputs defined for the custom API?","options":["As custom API request parameters and response properties","As canvas component input and output properties","As environment variables in the solution","As columns on the account table"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Custom APIs define their contract using request parameters (inputs) and response properties (outputs), which the associated plug-in reads and populates during execution.","source":{"title":"Create and use custom APIs — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/custom-api"}},{"id":"gen-30","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A custom API is designed so that no other developer should be able to register additional plug-in steps on its message, keeping the operation's behavior locked down. Which custom API setting controls this?","options":["The Is Function property","The Binding Type property","The Allowed Custom Processing Step Type property","The Execute Privilege Name property"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The 'Allowed custom processing step type' setting on a custom API determines whether, and at what stage, others may register additional steps; setting it to None prevents extra plug-in steps on the message.","source":{"title":"Create and use custom APIs — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/custom-api"}},{"id":"gen-31","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A design calls for a custom API that behaves like a query operation: it must be callable with a GET request, have no side effects, and always return a value. Which custom API configuration expresses this?","options":["Set Is Function to true so the message is exposed as an OData function","Set Binding Type to Entity Collection","Set the processing step type to Async Only","Register it as a webhook endpoint"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Marking a custom API as a function (Is Function = true) exposes it as an OData function callable with GET; functions are side-effect-free and must return a value, whereas actions are invoked with POST.","source":{"title":"Create and use custom APIs — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/custom-api"}},{"id":"gen-32","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"For an automation design, a process must start automatically whenever a new item is created in a SharePoint list and then update a Dataverse row. Which component and trigger style should you design?","options":["A scheduled cloud flow that polls the list on a timer","An instant cloud flow launched by a button press","A synchronous plug-in on the SharePoint list","An automated cloud flow started by a trigger event"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An automated cloud flow runs in response to an event (such as a new item being created), which matches an event-driven automation, unlike instant (manual) or scheduled (time-based) flows.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-33","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When designing a cloud flow, a maker needs to understand the two fundamental building blocks that make up any flow. What are they?","options":["Connectors and gateways","A trigger and one or more actions","Plug-ins and steps","Inputs and outputs"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Every cloud flow is composed of a trigger that starts it and one or more actions that run afterward to perform the work.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-34","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A business wants a flow that users can run on demand from a mobile app to send themselves a reminder. Which type of cloud flow should you design?","options":["An automated cloud flow","A scheduled cloud flow","An instant cloud flow","A desktop flow"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Instant cloud flows are triggered manually by a user, for example from a button in the mobile app, making them the right choice for on-demand execution.","source":{"title":"Create a cloud flow in Power Automate — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/get-started-logic-flow"}},{"id":"gen-35","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A pro developer must design a reusable dataset control that binds to a model-driven app grid and customizes how each row of Dataverse data is displayed. Which component type provides a dataset binding for this scenario?","options":["A canvas component with an input property","A PCF code component using a data-set property","A cloud flow with a Dataverse trigger","A custom connector action"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"PCF code components support a data-set binding that lets a developer build reusable controls over a collection of Dataverse records, such as customizing a grid's presentation in a model-driven app.","source":{"title":"Power Apps component framework overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/overview"}},{"id":"gen-36","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You need to design a connector so that its runtime behavior—such as setting a header or routing—can be adjusted without changing the underlying API, using a supported connector customization mechanism. Which custom connector feature supports this?","options":["Policy templates","Environment variables on the canvas app","Business rules","Plug-in registration steps"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Custom connectors can use policy templates to modify request/response behavior at runtime (for example transforming headers or values) without altering the backing REST API itself.","source":{"title":"Custom connectors overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/"}},{"id":"gen-37","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer registers a plug-in that calls the Dataverse Web API using a dedicated application user. Following the principle of least privilege, how should the application user be granted the permissions it needs to create and update rows in only two custom tables?","options":["Assign the application user the System Administrator role so no access issues occur during execution","Create a custom security role granting only the Create and Write privileges (at the appropriate access level) on those two tables, and assign it to the application user","Add the application user to the Environment Maker role, which restricts it to solution components","Share each row of the two tables directly with the application user as records are created"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Least privilege means creating a custom security role that grants only the specific privileges (Create, Write) at the minimum access level needed, rather than broad roles like System Administrator.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-38","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A server-side integration authenticates to Dataverse as an application (no interactive user). Which type of Dataverse user must exist and be assigned a security role for the integration to operate?","options":["A guest user invited through Microsoft Entra B2B collaboration","A stub user created automatically the first time a licensed user signs in","A service account with an interactive Power Apps per-user license","An application user linked to the Microsoft Entra app registration's client ID"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Single-tenant server-to-server authentication uses an application user in Dataverse that is associated with the Entra app registration's application (client) ID and must be assigned security roles.","source":{"title":"Use single-tenant server-to-server authentication — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-single-tenant-server-server-authentication"}},{"id":"gen-39","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A pro developer needs an isolated environment to build and test plug-ins and PCF components without affecting other makers, and wants it available at no additional licensing cost for individual development. Which environment type is the best fit?","options":["A Developer environment","A Production environment with a backup","A Default environment shared by the whole tenant","A Sandbox environment reset weekly"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Developer environments are intended for individual development and testing, are tied to a single owner, and are available through the Developer Plan without additional per-environment licensing.","source":{"title":"Create and manage environments — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/create-environment"}},{"id":"gen-40","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After registering an app in Microsoft Entra ID and creating the corresponding application user in Dataverse, a developer's code receives authorization errors when reading account rows. What is the most likely cause?","options":["The app registration is missing a redirect URI","The client secret has not been added to Azure Key Vault","No security role granting Read on the Account table has been assigned to the application user","The environment is a Developer environment, which blocks application users"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An application user only has the privileges granted by its assigned security roles; without a role that includes Read on the table, calls are denied even though authentication succeeds.","source":{"title":"Use single-tenant server-to-server authentication — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-single-tenant-server-server-authentication"}},{"id":"gen-41","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Within a Dataverse security role, a privilege such as Read is configured with an access level (for example User, Business Unit, Parent: Child Business Units, or Organization). What does the access level control?","options":["Which columns of a table the user can see","Whether the privilege applies to create versus update operations","The order in which security roles are evaluated when a user has several","The scope of rows the privilege applies to, based on ownership and business unit hierarchy"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Access levels determine the breadth (depth) of access — none, user/basic, business unit, parent-child business units, or organization — controlling which rows a privilege reaches based on ownership and business-unit hierarchy.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-42","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants each of several developers to have a personal space to build and validate solutions before promoting them, while keeping costs low. Which approach aligns with recommended environment management for development?","options":["Have all developers share the tenant's Default environment to simplify administration","Provision a separate Developer environment per developer for isolated build and test","Grant every developer the System Administrator role in the Production environment","Use a single Production environment and rely on solution layers to isolate work"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Managing development environments means giving developers isolated Developer environments to build and test without impacting shared or production environments.","source":{"title":"Create and manage environments — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/create-environment"}},{"id":"gen-43","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A custom API implemented as a plug-in must run in the security context of a background application user rather than an interactive user. Which authentication pattern is appropriate for the calling service?","options":["Delegated user authentication using the signed-in user's token","Shared connection reference using a service principal owned by the maker","Single-tenant server-to-server (S2S) authentication with an Entra app registration and Dataverse application user","Anonymous access secured by an API key in the request header"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Server-to-server authentication lets a service connect as an application user (via an Entra app registration) without an interactive user, which is the recommended pattern for background/service code.","source":{"title":"Use single-tenant server-to-server authentication — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-single-tenant-server-server-authentication"}},{"id":"gen-44","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Two users each have a security role. One role grants Read at the User level on Contact; the other grants Read at the Organization level on Contact. A user assigned both roles will have which effective access to Contact rows?","options":["Organization level, because privileges from multiple roles are cumulative and the broadest access applies","User level, because the most restrictive role wins","No access, because conflicting roles cancel each other","Business Unit level, as a default compromise between the two roles"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Security-role privileges are cumulative (least-restrictive union); when a user has multiple roles, the highest access level granted for a privilege applies.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-45","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer is troubleshooting why an application user cannot execute a newly registered custom API. All authentication succeeds. Which configuration should the developer verify first?","options":["That the app registration has a certificate instead of a client secret","That the environment has been converted from Sandbox to Production","That the application user has an interactive Power Apps license assigned","That the application user has a security role granting the privilege required to call the custom API's message"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Application users act only within their assigned security roles; an authorization failure after successful authentication points to a missing privilege on the role for the message being called.","source":{"title":"Use single-tenant server-to-server authentication — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-single-tenant-server-server-authentication"}},{"id":"gen-46","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes how privileges are organized in a Dataverse security role for a table?","options":["Each table has a single on/off toggle that grants full control","Privileges are defined per action — Create, Read, Write, Delete, Append, Append To, Assign, Share — each with its own access level","Privileges are inherited automatically from the environment's licensing tier","A role grants only Read; all write operations require a separate business rule"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Security roles define discrete table privileges (Create, Read, Write, Delete, Append, Append To, Assign, Share), each configurable to a specific access level, enabling fine-grained least-privilege design.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-47","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization wants to prevent developers from creating trial or production environments freely while still allowing sanctioned development. Which capability supports governing who can create environments?","options":["Row-level sharing on the environment table","A plug-in registered on the Create message of environments","Tenant-level environment creation governance settings in the Power Platform admin center","DLP policies applied to the Common Data Service connector"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Administrators can govern environment creation through tenant settings in the Power Platform admin center, controlling who may create environments as part of managing development environments.","source":{"title":"Create and manage environments — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/create-environment"}},{"id":"gen-48","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When configuring server-to-server authentication for Dataverse, which pairing correctly links the external identity to its Dataverse security context?","options":["The client secret is mapped directly to a security role without a user record","The tenant ID is added to a team, and the team is granted privileges","The redirect URI is registered as a Dataverse business unit","The Entra app registration's client ID is mapped to a Dataverse application user, which is then assigned security roles"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The application user is created with the Entra app registration's application (client) ID; assigning security roles to that application user establishes its Dataverse privileges.","source":{"title":"Use single-tenant server-to-server authentication — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-single-tenant-server-server-authentication"}},{"id":"gen-49","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer needs to move a completed, tested solution out of their personal Developer environment. Which describes the appropriate role of the Developer environment in this workflow?","options":["Developer environments are for building and testing; solutions are exported and deployed to downstream test/production environments","Developer environments are the recommended target for end users to consume the finished app","Developer environments automatically publish solutions to the tenant's Default environment on save","Developer environments cannot contain Dataverse and so cannot hold solutions"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Developer environments provide an isolated space to build and test; the resulting solution is then exported and deployed to other environments for testing and production use.","source":{"title":"Create and manage environments — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/create-environment"}},{"id":"gen-50","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A security review flags that a code component's application user was assigned the System Customizer role, granting far more than it uses. Which change best applies least privilege without breaking the integration?","options":["Leave the role as-is because application users are exempt from least-privilege guidance","Remove all roles and rely on the app registration's API permissions instead","Replace it with a custom role that grants only the specific table privileges and access levels the code actually needs","Add the System Administrator role temporarily to test, then leave it assigned"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Least privilege for code components means assigning a tailored custom security role containing only the required privileges at the minimum access levels, instead of broad built-in roles.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-51","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"What is the effect of a privilege being set to the access level 'None (Selected)' / no access for a table in a security role?","options":["The user can perform that action on rows they own only","The user is denied that action on the table entirely for that privilege","The user gets organization-wide access as a fallback","The privilege is inherited from the parent business unit"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Setting a privilege's access level to none denies that action on the table; higher levels (User, Business Unit, Parent-Child, Organization) progressively widen the scope of rows affected.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-52","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A single-tenant integration must access Dataverse in only one tenant using an Entra app registration. Which statement about the application user is correct?","options":["The application user does not appear in the environment's user list and is managed only in Azure","The application user automatically receives the same roles as the developer who created the app registration","The application user must be assigned a Dynamics 365 license before roles take effect","The application user is created within the target environment and appears among application users, where roles are assigned"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"For single-tenant S2S auth, the application user is created in the target Dataverse environment (listed among application users) and is granted the security roles that define its access.","source":{"title":"Use single-tenant server-to-server authentication — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-single-tenant-server-server-authentication"}},{"id":"gen-53","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"During troubleshooting, a developer confirms an application user's token is valid and the app registration's API permissions are consented, yet Create calls to a custom table fail. Which operational security setting is the most probable gap?","options":["The application user's security role omits the Create privilege on that custom table","The custom table lacks an alternate key","The environment's base language is not English","The plug-in is registered in the wrong pipeline stage"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When authentication and consent are correct but a specific action fails, the issue is typically a missing privilege on the application user's security role for that table and operation.","source":{"title":"Security roles and privileges — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/security-roles-privileges"}},{"id":"gen-54","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which environment type is designed to hold live business data and apps for end users, making it an inappropriate place for a developer to iterate on unfinished plug-in code?","options":["Developer environment","A personal build-and-test environment","Production environment","An isolated sandbox created per developer"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Production environments host live apps and data for end users; developers should build and test in isolated Developer (or sandbox) environments and deploy tested solutions to production.","source":{"title":"Create and manage environments — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/admin/create-environment"}},{"id":"gen-55","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your team develops customizations in a Dataverse environment and needs to move them to a separate test environment where makers must not be able to directly edit the components. Which solution type should you export and import to lock the components from in-place editing in the target?","options":["A managed solution","An unmanaged solution","The Default solution","A patch on an unmanaged solution"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Managed solutions are the deployable, sealed artifact for downstream (test/production) environments; their components can't be directly edited there, while unmanaged solutions are for development only.","source":{"title":"Application lifecycle management (ALM) overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/overview-alm"}},{"id":"gen-56","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants to store an API base URL that differs between Dev, Test, and Production so the same solution can be deployed to each environment without editing components. Which Dataverse feature is designed for this?","options":["A hard-coded value in a plug-in's unsecure configuration","A global option set shared across environments","A connection reference","An environment variable with a default value and per-environment current value"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Environment variables store configuration in a solution so a default value travels with the solution while a current (environment-specific) value is set per target, avoiding component edits across environments.","source":{"title":"Use environment variables in solutions — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/environmentvariables"}},{"id":"gen-57","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You import a managed solution that customizes a form, then later import a second managed solution from another publisher that also customizes the same form. In Dataverse solution layering, which layer's changes are displayed to users at runtime?","options":["The unmanaged (top) layer always wins regardless of import order","The layer from the solution imported first","The topmost managed layer, meaning the most recently imported managed solution wins for a given property","The system (bottom) layer defined by the base table"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"For managed solutions the layer nearest the top wins on a per-property basis, and the last managed solution imported sits highest, so its changes take effect (unless an unmanaged customization sits above all).","source":{"title":"Solution layers and merge behavior — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/solution-layers-alm"}},{"id":"gen-58","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your organization wants makers to deploy solutions from a development environment to test and production directly within Power Platform, without setting up Azure DevOps. Which capability should you configure?","options":["Power Platform pipelines","Power Platform Build Tools","Package Deployer command line","A GitHub Actions workflow"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Platform pipelines provide in-product, low-code deployment automation from a dev environment to target environments without requiring external CI/CD tooling like Azure DevOps.","source":{"title":"Overview of pipelines in Power Platform — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/pipelines"}},{"id":"gen-59","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You are building a CI/CD pipeline in Azure DevOps to export and import Dataverse solutions automatically. Which set of tools should you add to your pipeline?","options":["Power Apps CLI only, run from a local machine","Power Platform Build Tools tasks with a service connection to the target environment","In-product Power Platform pipelines configured in the host environment","Solution checker run manually before each release"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Platform Build Tools are the dedicated Azure DevOps tasks (export, import, pack/unpack, checker) that connect to environments via a service connection to automate ALM in a build/release pipeline.","source":{"title":"Power Platform Build Tools for Azure DevOps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/devops-build-tools"}},{"id":"gen-60","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Before exporting a solution, you want to confirm that every required component (such as a lookup's related table) will be present after import so the solution installs cleanly. What should you review?","options":["The solution's dependencies to ensure required components are included or already present in the target","The publisher prefix of each component","The current values of all environment variables","The managed properties of the solution package"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Solution dependencies list the components a solution requires; reviewing and resolving them prevents import failures caused by missing prerequisite components in the target environment.","source":{"title":"Application lifecycle management (ALM) overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/overview-alm"}},{"id":"gen-61","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A cloud flow inside a solution must reference an Azure Key Vault secret whose identifier differs per environment. What is the recommended way to make that secret reference portable across environments?","options":["Paste the secret value into the flow action at design time","Store the secret in the plug-in's secure configuration","Create a connection reference to Key Vault","Use an environment variable of the Azure Key Vault secret type"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Environment variables support an Azure Key Vault secret data type, letting solutions reference a secret whose location is set per environment without exposing or hard-coding the value.","source":{"title":"Use environment variables in solutions — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/environmentvariables"}},{"id":"gen-62","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer imported a managed solution into production, and now an administrator has directly edited one of its components in the production environment using the Default solution. What has happened to that component's layering?","options":["The managed solution was permanently modified in place","Nothing changed because managed components cannot be edited","An unmanaged (active) layer was created on top of the managed layer, and it now wins at runtime","The component reverted to its system default"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Editing a managed component directly creates an unmanaged customization layer above all managed layers; because the unmanaged layer sits on top, its values take effect and can mask future managed updates.","source":{"title":"Solution layers and merge behavior — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/solution-layers-alm"}},{"id":"gen-63","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your team currently makes changes directly in production and wants to adopt healthy ALM. According to Microsoft's ALM guidance, which practice should you adopt?","options":["Develop in unmanaged solutions in a dedicated dev environment and deploy managed solutions to downstream environments","Develop and ship everything as managed solutions in a single environment","Use the Default solution as the primary shipping vehicle","Export unmanaged solutions to production so admins can keep editing them"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Recommended ALM separates development (unmanaged solutions in a dev environment) from deployment (managed solutions in test/production), using source control and automation rather than editing production directly.","source":{"title":"Application lifecycle management (ALM) overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/overview-alm"}},{"id":"gen-64","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A pipeline deployment fails because a canvas app in the solution references a data connection that does not exist in the target environment. Which solution component was intended to keep that connection portable across environments?","options":["An environment variable","A connection reference","A solution patch","A managed property"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Connection references let solution apps and flows point to a named connection that is bound to an actual connection in each target environment, so credentials and endpoints don't have to be edited into the components.","source":{"title":"Application lifecycle management (ALM) overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/overview-alm"}},{"id":"gen-65","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Power Platform pipelines, where must the pipeline configuration (the pipelines app and deployment stage records) be installed to orchestrate deployments across your development and target environments?","options":["In each target (production) environment separately","In the developer's local Dataverse instance","In the Azure DevOps organization settings","In a dedicated host environment that references the development and target environments"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Platform pipelines are configured in a host environment where you define the pipeline and its stages that point to the source (dev) and target environments used for deployment.","source":{"title":"Overview of pipelines in Power Platform — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/pipelines"}},{"id":"gen-66","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You need your Azure DevOps release to authenticate to a Dataverse environment non-interactively as an application, so pipeline runs don't depend on a user's credentials. What should you configure for the Power Platform Build Tools tasks?","options":["A username/password stored in a plain-text pipeline variable","The developer's personal Microsoft account","A shared mailbox account with MFA disabled","A service connection using a service principal (application registration) or workload identity"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Build Tools tasks authenticate through a service connection; using a service principal / app registration enables secure, non-interactive automation instead of relying on user credentials.","source":{"title":"Power Platform Build Tools for Azure DevOps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/devops-build-tools"}},{"id":"gen-67","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A flow in your managed solution stops running after deployment because its environment variable has no value in the target environment. What is the correct fix that preserves ALM portability?","options":["Edit the flow in production to hard-code the value","Set the current value of the environment variable in the target environment","Change the environment variable to a global option set","Re-export the solution as unmanaged and import it"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Environment variables can be exported with only a default value; if none applies, you set the current value in each target environment (via the solution, pipeline, or admin) rather than editing components.","source":{"title":"Use environment variables in solutions — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/environmentvariables"}},{"id":"gen-68","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You want to see every layer that contributes to a single Dataverse component and identify which layer is currently active. Which capability should you use?","options":["The Solution checker report","The Solution layers view for the component","The environment variable definitions list","The pipeline run history"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Solution layers view shows the ordered stack of managed and unmanaged layers for a component, helping you troubleshoot which layer's values win at runtime.","source":{"title":"Solution layers and merge behavior — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/solution-layers-alm"}},{"id":"gen-69","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team of five developers is building one solution and wants to avoid overwriting each other's exported unmanaged solution files while enabling code review. Which ALM approach does Microsoft recommend?","options":["Store the single exported .zip in a shared network drive","Email the managed solution between developers","Unpack the solution with source control tools and commit the extracted components to a Git repository","Keep all work in the production Default solution"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Healthy ALM uses source control: unpacking the solution into its component files (for example with the Power Platform CLI) and committing them to Git enables branching, merging, and code review across a team.","source":{"title":"Application lifecycle management (ALM) overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/overview-alm"}},{"id":"gen-70","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"During an Azure DevOps release you want to block the deployment if the solution contains critical issues such as insecure plug-in patterns. Which Power Platform Build Tools task should you include in the pipeline?","options":["Export Solution","Set Solution Version","Solution Checker","Publish Customizations"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Solution Checker Build Tools task runs static analysis against best-practice rules and can fail the pipeline on critical findings, enforcing quality gates in CI/CD.","source":{"title":"Power Platform Build Tools for Azure DevOps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/devops-build-tools"}},{"id":"gen-71","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker uses a Power Platform pipeline to deploy a solution from Dev to Production. What form of the solution does the pipeline import into the target environment by default?","options":["An unmanaged solution so admins can keep editing it","A raw folder of unpacked component files","The Default solution export","A managed solution"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Pipelines follow ALM best practice by deploying managed solutions to downstream target environments, keeping those environments free of directly editable unmanaged customizations.","source":{"title":"Overview of pipelines in Power Platform — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/alm/pipelines"}},{"id":"gen-72","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You reference an environment variable inside a plug-in's logic. If the current value is not set in a given environment but a default value exists in the solution, what value does your code retrieve?","options":["Null, because current value is required","The default value defined in the solution","The value from the development environment","An error is thrown at run time"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When no current value is set, the environment variable resolves to its default value; the current value only overrides the default when present, which is why defaults provide a fallback across environments.","source":{"title":"Use environment variables in solutions — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/environmentvariables"}},{"id":"gen-73","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A canvas app needs to build a running total across the ordered rows of a collection, where each row's value depends on the accumulated result of the rows before it. Which Power Fx behavior should you rely on to accumulate state as you iterate the collection?","options":["The Sum function, because it inherently produces per-row running totals","A With function wrapped around a single Sum call over the whole table","A Sequence/ForAll pattern where each iteration references a variable holding the accumulated result","The Average function scoped to the ThisItem record"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Running totals are not a single aggregate; you iterate rows in order (for example with ForAll/Sequence) and accumulate into a variable, because Power Fx functions like Sum only return a single aggregate over the set, not per-row accumulations.","source":{"title":"Formula reference - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/formula-reference"}},{"id":"gen-74","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a canvas app you want a formula that evaluates an expensive lookup only once and then reuses that single result in several places within the same expression, without creating an app-scoped global variable. Which Power Fx function is designed for this?","options":["The With function, which defines named values scoped to a single record for use inside its formula","The Set function, which is the only way to name a value in Power Fx","The Collect function, which caches the value in a table","The UpdateContext function, which is required for any reuse of a value"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"With evaluates a record of named values and makes them available only inside its second argument, letting you compute something once and reuse it locally without a global or context variable.","source":{"title":"Formula reference - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/formula-reference"}},{"id":"gen-75","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You are shaping data in a canvas app and must transform each row of a table into a new record shape, producing a new table without modifying the source. Which Power Fx function produces a table by evaluating a formula for every record?","options":["Patch, which writes each record back to the data source","ForAll, which evaluates a formula for each record of a table and returns a table of results","GroupBy, which always returns a single scalar","Concurrent, which merges rows into one record"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"ForAll evaluates a formula for all records of a table and returns a table of the results, making it the function for row-by-row transformation and reshaping without mutating the source.","source":{"title":"Formula reference - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/formula-reference"}},{"id":"gen-76","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants to run several independent data-source calls at app start so they overlap instead of executing one after another, reducing load time. Which Power Fx function is intended to evaluate multiple formulas concurrently?","options":["Sequence, which forces the formulas to run strictly in order","ForAll, which guarantees parallel evaluation of every branch","Concurrent, which evaluates multiple formulas at the same time","Trace, which schedules background work"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Concurrent function evaluates multiple formulas at the same time within a single property, which can improve performance by overlapping otherwise sequential data operations such as initial loads.","source":{"title":"Formula reference - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/formula-reference"}},{"id":"gen-77","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You need to distinguish between a value that is truly absent (blank) and one that failed to parse. In Power Fx, which pair of functions correctly tests for a blank value and for an error condition, respectively?","options":["IsEmpty and IsNumeric","IsBlank and IsError","Coalesce and IfError only","Blank and Error only"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"IsBlank tests whether a value is blank, and IsError tests whether a value is an error; they address different conditions and are used together to write robust validation logic.","source":{"title":"Formula reference - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/formula-reference"}},{"id":"gen-78","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a canvas app formula you want to return the first non-blank value from a list of candidate expressions in a single, concise call rather than nesting several If statements. Which Power Fx function does this?","options":["Coalesce, which evaluates its arguments and returns the first that is not blank","Switch, which requires an exact match on a single expression","Filter, which returns a table rather than a scalar","First, which returns the first record of a table"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Coalesce evaluates its arguments in order and returns the first value that is not blank (and not an empty string), which is the idiomatic way to supply fallbacks without nested If statements.","source":{"title":"Formula reference - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/formula-reference"}},{"id":"gen-79","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants to trap an error from a risky operation and substitute a safe default so the app keeps running instead of showing an error banner. Which Power Fx function is purpose-built to run a fallback formula when the first argument produces an error?","options":["Notify, which only displays a message to the user","Validate, which checks a record against the data source","IfError, which returns a replacement value when its evaluated argument is an error","Assert, which stops app execution on failure"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"IfError evaluates its first value and, if it is an error, returns the specified replacement; it lets formulas detect and handle errors gracefully at the point they occur.","source":{"title":"Formula reference - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/formula-reference"}},{"id":"gen-80","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"How would you best describe Microsoft Power Fx to a developer new to the Power Platform?","options":["A proprietary imperative scripting language that only runs inside plug-ins","A strongly typed, declarative, low-code formula language derived from spreadsheet formulas","A visual drag-and-drop tool with no textual expressions","A dialect of C# compiled to IL at design time"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Fx is a general-purpose, strong-typed, declarative, and functional low-code language modeled on Excel-style formulas, and it recalculates values automatically as inputs change.","source":{"title":"Microsoft Power Fx overview - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/power-fx/overview"}},{"id":"gen-81","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team member argues that a Power Fx formula should re-run only when they manually trigger it, like a compiled procedure. Which characteristic of Power Fx best explains why values instead update on their own?","options":["Power Fx is imperative and executes top to bottom once per session","Power Fx caches all results permanently and never recomputes","Power Fx is declarative and recalculates automatically as the values it depends on change, like a spreadsheet","Power Fx requires an explicit Recalculate call before any value updates"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Like Excel, Power Fx is declarative: you describe the desired result, and the engine automatically recalculates a formula whenever the values it references change, without imperative re-execution.","source":{"title":"Microsoft Power Fx overview - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-platform/power-fx/overview"}},{"id":"gen-82","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You want to store several reusable canvas components (a branded header, a nav menu) so multiple apps can consume them and pick up centrally published updates. Which artifact should you create?","options":["A managed solution containing only the screens","A component library that holds shared components apps can consume and update from","A separate copy of each component pasted into every app","A PCF code component registered in Dataverse"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A component library is a container of reusable components that can be shared across canvas apps; consuming apps are notified of updates and can pull in the latest published versions.","source":{"title":"Component library - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/component-library"}},{"id":"gen-83","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An app consumes components from a component library. After the library author publishes an improved version, what does the consuming app experience?","options":["The app silently overwrites its own components with no indication","The app is notified that an updated version is available and can choose to update its instances","The app must be rebuilt from scratch to get any changes","The library changes are automatically forced into every consuming app immediately with no opt-in"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When a component library is republished, apps that use it are notified that a newer version exists and the maker can update the app to adopt the changes, keeping shared components in sync.","source":{"title":"Component library - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/component-library"}},{"id":"gen-84","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants a canvas component in a component library to pass a value back out to the screen that hosts it (for example, the currently selected item). Which component feature enables this outward data flow?","options":["An input custom property, which only sends data into the component","An output custom property, whose value the component sets and the host app reads","A global variable declared inside the component, which the host cannot see","A data source binding, which is required for any communication"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Custom properties can be defined as input or output; an output property lets the component expose a value that the consuming app reads, which is how a library component communicates results back to its host.","source":{"title":"Component library - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/component-library"}},{"id":"gen-85","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You want components in a component library to be governed by solutions, managed with ALM, and reused across an environment. What is the recommended approach for such reusable canvas components?","options":["Keep components only inside individual apps and export each app separately","Create component libraries and include them in solutions so they move across environments with ALM","Copy and paste the components into each app to avoid dependencies","Store the component definitions as loose files outside any solution"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Component libraries are the recommended way to build and share reusable components, and they can be added to solutions so they participate in application lifecycle management across environments.","source":{"title":"Component library - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/component-library"}},{"id":"gen-86","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a canvas app you have added a Power Automate cloud flow to a button. Which Power Fx syntax starts the flow and can pass parameters to it?","options":["FlowName.Start() with no arguments allowed","Power Automate.Invoke(FlowName)","FlowName.Run(parameters), calling the flow like a function","Trigger(FlowName) from the button's OnStart"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"After a flow is associated with a control, you call it with FlowName.Run(...), passing any input parameters as arguments, to start the cloud flow from within the canvas app.","source":{"title":"Start a flow in a canvas app - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/using-logic-flows"}},{"id":"gen-87","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A cloud flow is meant to be started from a canvas app with the .Run() call. Which trigger must the flow use so it can be added to and called from the app?","options":["A scheduled recurrence trigger","The Power Apps (V2) trigger, which lets the app call the flow and define input parameters","A Dataverse 'When a row is added' trigger","An HTTP request trigger that bypasses the connector"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"To be callable from a canvas app, the flow must begin with the Power Apps trigger (the Power Apps V2 trigger), which exposes it to the app and lets you define typed input parameters received in Run().","source":{"title":"Start a flow in a canvas app - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/using-logic-flows"}},{"id":"gen-88","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your canvas app must display a value that a cloud flow calculates and returns (for example, an approval reference number). How should the app capture the flow's output?","options":["Read a global variable that the flow writes directly into the app","Assign the result of FlowName.Run(...) to a variable, because the flow returns its response values to the caller","The flow cannot return anything to a canvas app; outputs are impossible","Poll a Dataverse table because Run() never yields a return value"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When the flow uses a Respond to Power Apps action, FlowName.Run(...) returns those output values to the app, so you capture them by setting a variable to the result of the Run call.","source":{"title":"Start a flow in a canvas app - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/using-logic-flows"}},{"id":"gen-89","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker wants to add an existing cloud flow to a canvas app so a control can invoke it. From within Power Apps Studio, where do they do this?","options":["By editing the app's manifest XML by hand","Through the Power Automate pane, which lets you add a flow to the app and then reference it in a control's formula","Only by publishing a custom connector first","By registering the flow with the Plug-in Registration Tool"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In Power Apps Studio you use the Power Automate pane to add an existing (or new) flow to the app; once added, the flow is available to call from a control property with FlowName.Run().","source":{"title":"Start a flow in a canvas app - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/using-logic-flows"}},{"id":"gen-90","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer writes a complex Power Fx expression and wants to output diagnostic information to Monitor to help debug the formula's intermediate values. Which Power Fx function is intended to emit custom information into the trace for analysis?","options":["Trace, which adds custom information to the Monitor session for debugging","Print, which writes to a console window","Debug, which pauses formula evaluation","Log, which stores messages in Dataverse automatically"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Trace function adds custom information to the Monitor trace stream, letting a developer inspect intermediate values and behavior of complex formulas while debugging a canvas app.","source":{"title":"Formula reference - canvas apps - Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/formula-reference"}},{"id":"gen-91","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A canvas app is intermittently returning throttling errors, but users cannot reproduce it on demand. You want a live, per-operation event stream that shows each data source call, its duration, and the exact request URL for both the canvas app and a related model-driven app. Which tool should you use first?","options":["Monitor","Solution Checker","The Power Platform admin center analytics reports","Application Insights alerts only"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Monitor (Live monitor) streams a live log of every event in an app session — data source calls, formula evaluation, navigation — with per-operation durations and request details, and it works for both canvas and model-driven apps.","source":{"title":"Live monitor overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/monitor-overview"}},{"id":"gen-92","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer claims Monitor can only be used to debug canvas apps. Which statement correctly describes Monitor's scope?","options":["Monitor only captures OnStart events and ignores everything else","Monitor works only in Power Apps Studio during editing, never on a published app","Monitor works for both canvas and model-driven apps and streams a full session event log","Monitor is limited to model-driven apps and their form load events"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Monitor supports both canvas and model-driven apps, capturing a full stream of session events with per-operation timing and detail, and it can attach to a published app session.","source":{"title":"Live monitor overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/monitor-overview"}},{"id":"gen-93","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"While reviewing a slow canvas screen in Monitor, you notice one Dataverse operation with a status of 429 and a long duration that repeats several times. What does the 429 status most likely indicate?","options":["The record was not found","The user lacks the security privilege for the table","The formula contains a syntax error","The requests are being throttled by service protection limits"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In Monitor (and browser F12 Network), an HTTP 429 status signals the requests are being throttled; the fix is to reduce call frequency through caching, concurrency, or batching rather than retrying blindly.","source":{"title":"Live monitor overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/monitor-overview"}},{"id":"gen-94","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You want to inspect the exact OData query and raw HTTP response payload that a canvas app sends to Dataverse when a gallery loads, to confirm which columns are being retrieved. Which approach gives you that per-request detail?","options":["Open the detail pane of the operation's row in Monitor to view the request URL, OData query, and response","Read the app's OnStart formula and infer the query","Check the Dataverse table's audit history","Export the app package and open the .msapp file"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Each Monitor row exposes a detailed pane showing the request URL, the OData query sent, and the response payload or error, letting you confirm exactly what the app requested from Dataverse.","source":{"title":"Live monitor overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/monitor-overview"}},{"id":"gen-95","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A canvas app filters a Dataverse table containing 40,000 rows, and users report that some records they expect to see are simply missing from the gallery. In Studio, the formula shows a blue-dot warning. What is the root cause?","options":["The security role is filtering out the rows","The formula is non-delegable, so only the first page of records is evaluated locally","The gallery's Items property is set to a static collection","The table has row-level sharing enabled"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A non-delegable query causes Power Apps to retrieve only the first page (the data row limit) and process the rest locally, so matching records beyond that page are silently dropped — signaled by the blue delegation warning.","source":{"title":"Understand delegation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"gen-96","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your app misses records because of a non-delegable query on a large Dataverse table. A colleague suggests raising the data row limit from 500 to 2000 to fix it. Why is this a poor solution?","options":["The maximum data row limit is actually 5000, so 2000 is too low","Raising the limit disables delegation entirely for all data sources","The query is still non-delegable, so it only enlarges the retrieved page while rows beyond it are still ignored","Changing the limit requires a Dataverse administrator and is not available to makers"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Raising the row limit only makes the locally processed page larger; the query remains non-delegable, so records beyond the new cap are still missed. The correct fix is to make the query delegable.","source":{"title":"Understand delegation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"gen-97","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"What is the default number of records a non-delegable query retrieves in a canvas app, and what is the maximum you can configure it to?","options":["Default 500; configurable up to 2000","Default 100; configurable up to 1000","Default 1000; configurable up to 4000","Default 2000; configurable up to 10000"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The data row limit defaults to 500 and can be raised to a maximum of 2000 in app settings; beyond that, delegation is required to return correct results.","source":{"title":"Understand delegation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"gen-98","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Delegation determines whether Power Apps pushes processing to the data source. Which factor combination determines if a particular operation is delegable?","options":["Only the size of the table being queried","Only the user's security role and access level","The combination of the data source and the specific function or operator used","Only whether the app is canvas or model-driven"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Delegation support depends on both the data source and the function/operator; a function that is delegable on Dataverse may not be delegable on another source, so both must support the operation.","source":{"title":"Understand delegation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"gen-99","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A canvas app stores reference data in an in-memory collection built with ClearCollect at startup. A developer worries that filtering this collection will hit delegation limits. What is the correct understanding?","options":["Collections are always delegated to Dataverse automatically","In-memory collections do not need delegation, but they are still capped by the data row limit when populated","Collections cannot be filtered in canvas apps","Filtering a collection always returns wrong results regardless of size"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In-memory collections and imported static sources are held locally, so delegation does not apply, but the amount loaded is still bounded by the data row limit when it is populated from a data source.","source":{"title":"Understand delegation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"gen-100","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which data sources are considered highly delegable in canvas apps, allowing filtering and sorting to be pushed to the server for large tables?","options":["Imported Excel files stored in the app","Static in-memory collections","Dataverse and SQL Server","The Objects/JSON of a static variable"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dataverse and SQL Server are highly delegable, so delegable functions on them push filtering, sorting, and aggregation to the server; static/imported and in-memory sources are held in memory and capped by the row limit.","source":{"title":"Understand delegation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"gen-101","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An app reaches its first screen in about 15 seconds. Its OnStart runs eight sequential ClearCollect calls against different Dataverse tables. Which change most directly reduces the startup time while keeping the data available?","options":["Wrap the independent loads in Concurrent() so they run in parallel","Move all eight ClearCollect calls into a single button's OnSelect","Increase the data row limit to 2000","Convert the app to a model-driven app"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Concurrent() runs independent operations in parallel instead of one after another, cutting the cumulative OnStart time; you can also defer non-essential loads to each screen's OnVisible.","source":{"title":"How to create performant Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-performant-apps-overview"}},{"id":"gen-102","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"To make the first screen of a canvas app paint quickly, where should you place reference-data loads that are only needed on later screens?","options":["In the app's OnStart so everything is ready up front","In the OnVisible of the specific screens that need the data","In the App.Formulas as named formulas that never evaluate","In each control's OnSelect handler"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Moving non-global loads from OnStart to a screen's OnVisible lets the first screen render fast and hydrates other screens on demand, reducing perceived startup time.","source":{"title":"How to create performant Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-performant-apps-overview"}},{"id":"gen-103","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which set of practices best reduces the number of calls and improves canvas app performance at startup?","options":["Add more connectors and data sources so data is always fresh","Increase the number of controls per screen to reduce navigation","Cache reference data in collections, limit data sources, and select only needed columns","Replace all variables with repeated LookUp calls to always read live data"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Caching reference data into collections, limiting the number of data sources/connectors, and selecting only the columns you need all reduce network calls and speed up the app.","source":{"title":"How to create performant Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-performant-apps-overview"}},{"id":"gen-104","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A formula repeatedly calls LookUp against the same Dataverse table each time a label needs a value, causing many network requests. What is the recommended optimization?","options":["Cache the looked-up value in a variable or collection and reference that instead of repeating the lookup","Move the LookUp into OnStart but keep calling it from every label","Raise the delegation limit to reduce the number of calls","Disable delegation on the data source"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Repeated lookups issue repeated network requests; caching the result in a variable or collection avoids re-querying the server and reduces the call count.","source":{"title":"How to create performant Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-performant-apps-overview"}},{"id":"gen-105","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A model-driven main form is slow to open. It has 60 fields on a single primary tab, three subgrids that are expanded by default, and two synchronous OnLoad scripts. Which change set most improves form load time?","options":["Add more subgrids so users scroll less","Distribute fields across secondary tabs, set subgrids and secondary tabs to load on demand, and make OnLoad scripts asynchronous","Convert every field to a business rule","Increase the browser cache size on each client machine"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Model-driven form load is dominated by the number of controls, subgrids, and tabs plus synchronous work; moving fields to secondary tabs, deferring subgrids/tabs to on-demand load, and making scripts asynchronous reduces load time.","source":{"title":"How to create performant Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-performant-apps-overview"}},{"id":"gen-106","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When writing client scripts for a model-driven form, which practice best supports performance?","options":["Register every possible event handler so nothing is missed","Retrieve all columns of related records with unbounded queries","Use synchronous Xrm.WebApi calls to guarantee ordering","Use asynchronous Xrm.WebApi calls and request only needed columns with $select"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Efficient client scripting registers only necessary handlers, favors asynchronous Xrm.WebApi calls, and requests only the columns needed via $select to avoid unbounded retrieves that slow form load.","source":{"title":"How to create performant Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-performant-apps-overview"}},{"id":"gen-107","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You must prove which operation causes intermittent throttling in a published canvas app and confirm the raw HTTP calls involved. Which combination of tools and steps is most appropriate?","options":["Attach Monitor to the published session, reproduce the issue to find the 429 operation, then cross-check the request in browser F12 Network","Only read the app's formulas in Studio and guess the slow operation","Run Solution Checker and fix all flagged rules","Increase the data row limit and republish the app"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Monitor attaches to a published session and reveals the operation returning 429 with its duration and payload; the browser F12 Network tab complements it by showing the raw HTTP call, so you can then reduce call frequency or batch requests.","source":{"title":"How to create performant Power Apps — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/create-performant-apps-overview"}},{"id":"gen-108","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A canvas app uses Filter(Accounts, StartsWith(Name, txtSearch.Text)) over a 40,000-row Dataverse table and does not show the blue delegation warning. Which conclusion is correct?","options":["The query is delegable on Dataverse, so filtering is pushed to the server and returns correct results","The absence of a warning means delegation is broken","The query will only ever return 500 records regardless","You must raise the row limit to 2000 for it to work"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When no delegation warning appears, the function and operator are delegable on that data source (StartsWith is delegable on Dataverse), so the predicate is evaluated on the server and all matching rows are returned.","source":{"title":"Understand delegation — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/delegation-overview"}},{"id":"gen-109","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer needs to run a JavaScript function when a user changes the value of the 'creditlimit' column on an account form. Which event should the function be registered on to fire immediately after the field loses focus with a new value?","options":["The form OnLoad event","The column OnChange event","The form OnSave event","The form data OnLoad event"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The OnChange event of a column fires when the column value is changed and the control loses focus, making it the correct place to react to edits of a specific field.","source":{"title":"Events in forms and grids — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/events-forms-grids"}},{"id":"gen-110","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a form OnSave event handler, a developer wants to prevent the record from being saved when a validation check fails. Which method should be called on the event arguments?","options":["executionContext.getFormContext().data.refresh()","formContext.ui.close()","Xrm.Page.data.save(false)","eventArgs.preventDefault()"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Calling getEventArgs().preventDefault() in an OnSave handler cancels the save operation, which is the supported way to block a save when validation fails.","source":{"title":"Events in forms and grids — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/events-forms-grids"}},{"id":"gen-111","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants their client script functions to receive a reference to the form they are running against without relying on the deprecated global Xrm.Page. What is the recommended approach?","options":["Read the form context from window.parent.Xrm.Page","Instantiate a new Xrm.FormContext object in code","Enable the 'Pass execution context as first parameter' option and call executionContext.getFormContext()","Store the form context in localStorage during OnLoad"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When registering a handler you enable 'Pass execution context as first parameter', then call executionContext.getFormContext() to obtain the form context, replacing the deprecated Xrm.Page.","source":{"title":"Client scripting: JavaScript — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/client-scripting"}},{"id":"gen-112","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Client-side JavaScript must be added to a model-driven app so it can be referenced by form event handlers and deployed as part of a solution. What component should the code be stored in?","options":["An HTML web page in Azure Blob Storage","A JavaScript (JScript) web resource","A plug-in assembly registered on the message pipeline","An environment variable of type JSON"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Client scripting code is stored in a JavaScript web resource, which can be added to a solution and referenced by form and command event handlers.","source":{"title":"Client scripting: JavaScript — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/client-scripting"}},{"id":"gen-113","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer needs to retrieve a single account record's name and revenue from client script and display it in a notification. Which Xrm.WebApi method should be used?","options":["Xrm.WebApi.online.execute()","Xrm.WebApi.retrieveMultipleRecords()","Xrm.WebApi.createRecord()","Xrm.WebApi.retrieveRecord()"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Xrm.WebApi.retrieveRecord() retrieves a single record by its table name and ID, optionally using an OData $select to limit columns.","source":{"title":"Xrm.WebApi reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/reference/xrm-webapi"}},{"id":"gen-114","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"From a form OnLoad handler, a developer wants to query all active contacts for the current account using an OData filter. Which method returns a collection of matching records?","options":["Xrm.WebApi.retrieveRecord()","Xrm.WebApi.retrieveMultipleRecords()","formContext.data.entity.getDataXml()","Xrm.Navigation.openForm()"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Xrm.WebApi.retrieveMultipleRecords() runs an OData query (with $select, $filter, etc.) and returns a collection of matching records asynchronously.","source":{"title":"Xrm.WebApi reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/reference/xrm-webapi"}},{"id":"gen-115","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer must set the value of the 'telephone1' attribute on the current form and mark it as dirty so it saves. Which Client API path is correct?","options":["formContext.getControl('telephone1').setValue('555-0100')","formContext.ui.setValue('telephone1', '555-0100')","Xrm.WebApi.updateRecord('telephone1', '555-0100')","formContext.getAttribute('telephone1').setValue('555-0100')"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Attribute values are read and written through formContext.getAttribute(name).setValue(); setting a value through the attribute marks it dirty so it is included in the save.","source":{"title":"Client API Reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/reference"}},{"id":"gen-116","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A script needs to hide a section on the form based on a field value. The section is a UI element, not data. Which Client API object exposes visibility control for it?","options":["formContext.data","formContext.getAttribute()","formContext.ui (controls, sections, tabs)","Xrm.WebApi"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The formContext.ui object represents the user interface, giving access to tabs, sections, and controls where methods like setVisible() are used; formContext.data is for the underlying record data.","source":{"title":"Client API Reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/reference"}},{"id":"gen-117","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants a command bar button to be enabled only when a specific field on the form is populated. Where should the JavaScript enable/disable logic be attached?","options":["As a form OnLoad event handler that toggles the button","As an Enable Rule (custom rule) that calls a JavaScript function returning true/false","As a plug-in step on the Retrieve message","As a business rule on the table"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Command visibility and enablement are controlled by command rules; a custom Enable Rule can call a JavaScript function that returns a Boolean to enable or disable the button.","source":{"title":"Client scripting: JavaScript — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/client-scripting"}},{"id":"gen-118","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In client script, which method displays a form-level notification banner that stays visible until it is explicitly cleared?","options":["formContext.ui.setFormNotification(message, level, uniqueId)","Xrm.Navigation.openAlertDialog(message)","formContext.getAttribute('x').setNotification(message)","console.warn(message)"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"formContext.ui.setFormNotification() shows a persistent notification at the form level identified by a uniqueId, which can later be removed with clearFormNotification().","source":{"title":"Client API Reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/reference"}},{"id":"gen-119","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer registers a handler that must run whenever any field's data is refreshed after the record loads asynchronously. Which event is designed to fire after form data has finished loading?","options":["OnSave","OnChange","Data OnLoad (formContext.data addOnLoad)","TabStateChange"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The data OnLoad event, registered via formContext.data.addOnLoad, occurs when the form's data finishes loading or is refreshed, separate from the initial form OnLoad.","source":{"title":"Events in forms and grids — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/events-forms-grids"}},{"id":"gen-120","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A client script needs to create a new task record in Dataverse when a button is clicked, without a full page postback. Which Xrm.WebApi method should be called?","options":["Xrm.WebApi.createRecord(entityLogicalName, data)","formContext.data.save()","Xrm.Navigation.newRecord()","Xrm.WebApi.retrieveMultipleRecords()"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Xrm.WebApi.createRecord() asynchronously creates a record of the specified table using the provided data object and returns the new record's ID.","source":{"title":"Xrm.WebApi reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/reference/xrm-webapi"}},{"id":"gen-121","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A command bar button must open a custom page and pass the current record ID to it. Which Client API object provides the method to navigate to a custom page?","options":["Xrm.WebApi","formContext.data.entity","Xrm.Utility.getGlobalContext","Xrm.Navigation (navigateTo)"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Xrm.Navigation.navigateTo() opens navigation targets including custom pages, and accepts page input and navigation options to pass context such as a record ID.","source":{"title":"Client API Reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/reference"}},{"id":"gen-122","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants a function to fire only when a specific field on a subgrid changes, but subgrids do not load until their tab is expanded. What is the recommended way to register the subgrid OnLoad handler reliably?","options":["Register the subgrid OnLoad handler inside the form OnLoad, after using getControl to reach the grid","Register it as a plug-in on the RetrieveMultiple message","Add it to the JavaScript web resource's top-level scope so it runs on file load","Register it as a business rule scoped to the entity"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Because grid controls may not be available until loaded, the guidance is to add the grid OnLoad handler from within the form OnLoad handler once the control can be retrieved with getControl.","source":{"title":"Events in forms and grids — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/events-forms-grids"}},{"id":"gen-123","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes when to choose client scripting over a business rule to implement form logic in a model-driven app?","options":["Business rules should be used whenever any conditional logic is required, and client scripting is deprecated","Client scripting is appropriate for complex logic such as calling the Web API or custom validation that business rules cannot express","Client scripting runs on the server, so it is preferred for enforcing data integrity","Business rules can call Xrm.WebApi, so client scripting is only for styling"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Business rules handle simple declarative form logic, while client scripting (JavaScript) is used for more complex requirements such as calling the Web API, custom validation, and manipulating the UI beyond what business rules support.","source":{"title":"Client scripting: JavaScript — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/client-scripting"}},{"id":"gen-124","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer must update an existing account record's revenue from client script. Which Xrm.WebApi method and parameter set is correct?","options":["Xrm.WebApi.updateRecord(entityLogicalName, id, data)","Xrm.WebApi.createRecord(id, data)","Xrm.WebApi.retrieveRecord(entityLogicalName, data)","formContext.getAttribute('revenue').save()"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Xrm.WebApi.updateRecord() takes the table logical name, the record ID, and a data object of columns to update, performing an asynchronous update.","source":{"title":"Xrm.WebApi reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/reference/xrm-webapi"}},{"id":"gen-125","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A script needs to determine whether the form is currently in Create mode versus Update mode to decide which defaults to apply. Which Client API call returns the form type?","options":["formContext.data.entity.getEntityName()","Xrm.WebApi.getFormType()","formContext.ui.getFormType()","formContext.getAttribute('formtype').getValue()"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"formContext.ui.getFormType() returns a numeric value indicating the current form context (for example, Create, Update, or Read Only), letting the script branch accordingly.","source":{"title":"Client API Reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/reference"}},{"id":"gen-126","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants an OnSave handler to distinguish between a normal save and a save-and-close so it can behave differently. Which object provides the save mode value?","options":["formContext.ui.getSaveMode()","formContext.data.getSaveMode()","Xrm.WebApi.getSaveMode()","executionContext.getEventArgs().getSaveMode()"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In an OnSave handler, executionContext.getEventArgs().getSaveMode() returns the code identifying how the save was triggered (such as Save, Save and Close, or Autosave).","source":{"title":"Events in forms and grids — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/model-driven-apps/clientapi/events-forms-grids"}},{"id":"gen-127","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You are building a PCF code component using TypeScript and initialize it with the CLI. Which method is called first when the component is loaded onto a form, giving you the container element and access to the component's context?","options":["updateView","getOutputs","destroy","init"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"init is the first lifecycle method invoked when the component is initialized; it receives context, notifyOutputChanged, state, and the container div where you render your UI.","source":{"title":"Create your first component — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/implementing-controls-using-typescript"}},{"id":"gen-128","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a code component's lifecycle, which method does the framework call whenever data or property values bound to the control change, so you can re-render the UI with the updated context?","options":["updateView","init","destroy","notifyOutputChanged"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"updateView is called when any value in the property bag changes (data, layout, mode); it receives the updated context and is where you refresh the rendered output.","source":{"title":"Create your first component — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/implementing-controls-using-typescript"}},{"id":"gen-129","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your PCF component lets a user edit a value locally and must push the new value back to the bound column. What must your code do to tell the framework a new output value is ready to be read?","options":["Directly assign the value to context.parameters","Return the value from init","Call notifyOutputChanged so the framework then calls getOutputs","Set the value inside the destroy method"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Calling notifyOutputChanged signals the framework that outputs have changed; the framework responds by calling getOutputs to retrieve the new values and commit them.","source":{"title":"Create your first component — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/implementing-controls-using-typescript"}},{"id":"gen-130","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A code component attaches event listeners and creates DOM elements during its lifetime. In which method should you remove event handlers and clean up resources to avoid memory leaks when the component is removed?","options":["updateView","getOutputs","destroy","init"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"destroy is called when the component is removed from the DOM; use it to detach event handlers and release resources so no memory leaks occur.","source":{"title":"Create your first component — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/implementing-controls-using-typescript"}},{"id":"gen-131","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which file in a PCF project defines the component's metadata — its namespace, constructor, properties, and required resources — that the platform reads to know how to render and bind the control?","options":["index.ts","ControlManifest.Input.xml","package.json","tsconfig.json"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"ControlManifest.Input.xml is the manifest that describes the control element, its properties, data-sets, and resources; the platform uses it to load and bind the component.","source":{"title":"PCF manifest schema reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/manifest-schema-reference/"}},{"id":"gen-132","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You need your code component to bind to a single field on a form (for example a text or whole-number column). Which manifest element should you use to declare that bound input?","options":["data-set","resources","feature-usage","property"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A property element binds the component to a single value/field on a form, specifying its of-type and usage; data-set is used instead when binding to a collection of records.","source":{"title":"PCF manifest schema reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/manifest-schema-reference/"}},{"id":"gen-133","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You want to build a code component that operates over a grid/list of records rather than a single field. Which manifest element declares this binding?","options":["property","type-group","data-set","resources"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The data-set element binds a component to a collection of records (a view/grid), enabling dataset components used on views and subgrids.","source":{"title":"PCF manifest schema reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/manifest-schema-reference/"}},{"id":"gen-134","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the manifest, where do you list the JavaScript bundle, CSS, and localized RESX strings that the code component needs at runtime?","options":["Within the resources element","As attributes of the control element","Inside each property element","In the type-group element"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The resources element declares the code (bundle), CSS, and resx files the component loads at runtime; the platform packages these together.","source":{"title":"PCF manifest schema reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/manifest-schema-reference/"}},{"id":"gen-135","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which Power Platform CLI command scaffolds a new code component project, creating the manifest and TypeScript project structure?","options":["pac solution init","pac pcf init","pac pcf push","npm run build"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"pac pcf init scaffolds a new code component project with the ControlManifest and TypeScript files; namespace, name, and template are supplied as parameters.","source":{"title":"Create and build a code component — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/create-custom-controls-using-pcf"}},{"id":"gen-136","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After scaffolding a code component with pac pcf init, which command installs dependencies and builds the project so you can test it in the local test harness?","options":["npm run build (after npm install)","pac solution import","pac auth create","pac pcf push"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"You run npm install to pull dependencies, then npm run build to compile the component; npm start runs the local test harness for iterative development.","source":{"title":"Create and build a code component — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/create-custom-controls-using-pcf"}},{"id":"gen-137","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You want to quickly push a code component to a Dataverse environment during development without manually building and importing a solution zip. Which CLI command deploys it directly?","options":["pac pcf init","pac org select","npm run refreshTypes","pac pcf push"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"pac pcf push builds and imports the component into the connected environment for rapid development iteration; it requires an authenticated profile to the target org.","source":{"title":"Create and build a code component — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/create-custom-controls-using-pcf"}},{"id":"gen-138","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"To distribute a code component through normal ALM across environments, what is the recommended packaging approach for production deployment?","options":["Copy the bundle.js file into a web resource","Add the component to a Dataverse solution and export/import it (managed for production)","Email the .pcfproj folder to admins","Use pac pcf push against the production org"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"For proper ALM, the code component is added to a solution and moved between environments as a managed solution; pac pcf push is only intended for development iteration.","source":{"title":"Create and build a code component — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/create-custom-controls-using-pcf"}},{"id":"gen-139","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker asks why they should invest in PCF code components instead of traditional HTML web resources. Which statement best reflects an advantage of code components?","options":["Code components run only in the browser and cannot access Dataverse data","Code components are rendered as part of the app and provide a first-class, performant UI bound to the platform's data and metadata","Code components require no manifest or lifecycle methods","Code components can only be used in canvas apps"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Unlike web resources hosted in iframes, code components are rendered as part of the app with direct access to framework APIs, data binding, and metadata, giving better performance and integration.","source":{"title":"Power Apps component framework overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/overview"}},{"id":"gen-140","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which set of app types can consume Power Apps component framework code components?","options":["Only model-driven apps","Only canvas apps","Only classic web resources","Model-driven apps, canvas apps, and portals/Power Pages"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Code components can be used across model-driven apps, canvas apps, and Power Pages, making them reusable UI building blocks throughout the platform.","source":{"title":"Power Apps component framework overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/overview"}},{"id":"gen-141","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your code component must query additional Dataverse records beyond the bound column, for example to look up related rows. Which context feature exposes methods such as retrieveMultipleRecords for this?","options":["context.device","context.utils","context.webAPI","context.formatting"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"context.webAPI provides methods like retrieveMultipleRecords, retrieveRecord, and createRecord so the component can perform CRUD operations against Dataverse.","source":{"title":"Power Apps component framework overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/overview"}},{"id":"gen-142","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A code component needs to let the user capture a photo or pick a file from their device. Which context feature exposes captureImage and pickFile methods?","options":["context.device","context.webAPI","context.navigation","context.mode"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"context.device exposes device-capability methods such as captureImage, captureAudio, captureVideo, pickFile, and getCurrentPosition for interacting with hardware.","source":{"title":"Power Apps component framework overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/overview"}},{"id":"gen-143","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Before your code component can call device or Web API features at runtime, what must you declare so the platform enables and includes those capabilities?","options":["The feature usage in the manifest (for example the feature-usage/uses-feature declaration)","A new plug-in step in the Registration Tool","An environment variable in the solution","A security role privilege on the table"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Features such as Device, Utility, and WebAPI must be declared in the manifest's feature-usage element so the framework provisions those APIs to the component.","source":{"title":"PCF manifest schema reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/manifest-schema-reference/"}},{"id":"gen-144","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"During init, the framework passes a notifyOutputChanged callback. What is the correct way to use it?","options":["Call it once inside destroy to flush pending values","Return it from getOutputs so the framework can subscribe","Pass it to the manifest as a property attribute","Store the reference and invoke it later whenever the component has new output values to commit"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The component saves the notifyOutputChanged callback provided in init and calls it whenever its output values change, prompting the framework to call getOutputs.","source":{"title":"Create your first component — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/component-framework/implementing-controls-using-typescript"}},{"id":"gen-145","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You must validate an incoming Account create and cancel it for unauthorized callers even when the calling user lacks the Create privilege on the table. In which pipeline stage should you register the synchronous step?","options":["Post-operation (stage 40), because that is the only stage where you can throw an exception.","Pre-operation (stage 20), because it runs inside the transaction after security checks.","Pre-validation (stage 10), because it runs outside the transaction and before Dataverse performs security/privilege checks.","Main operation (stage 30), because custom logic replaces the core create."],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Pre-validation is the only stage that runs outside the database transaction and before security checks, so its logic executes even when the initiating user lacks privilege, making it ideal for early validation and cancellation.","source":{"title":"Event framework — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/event-framework"}},{"id":"gen-146","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a plug-in on the Update message you need to change a value on the record being saved so the new value is persisted without issuing a second Update call. Which stage lets you modify the Target so the change is written as part of the same operation?","options":["Pre-operation (stage 20) — it runs inside the transaction before the write, so modifications to the Target entity are persisted with the operation.","Post-operation (stage 40) — the record is already committed, so editing the Target here saves automatically.","Pre-validation (stage 10) — changes here are the only ones guaranteed to persist.","Any asynchronous step, because async steps always write their Target back to the database."],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Pre-operation runs inside the transaction before the change is written, so attributes set on the Target entity are saved as part of the operation without needing a separate Update.","source":{"title":"Event framework — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/event-framework"}},{"id":"gen-147","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A plug-in calls an external billing REST service that can take several seconds and must not delay the user submitting an order. You register the step to run asynchronously. Which stage must you choose, and how does it run?","options":["Pre-validation, running inline before the transaction begins.","Pre-operation, queued but blocking the user until it completes.","Main operation, replacing the core create with your async code.","Post-operation, queued as a background system job (asyncoperation) that runs after the operation commits and does not block the user."],"correct":[3],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Asynchronous steps are valid only in the post-operation stage; they are queued as system jobs (asyncoperation rows) executed by the async service after the operation completes, so the user is not blocked.","source":{"title":"Use plug-ins to extend business processes — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/plug-ins"}},{"id":"gen-148","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"On an Update step, the Target entity holds only the attributes that changed, but your audit logic needs the value of a column that was NOT modified in this update. What is the correct way to obtain that previous value?","options":["Call service.Retrieve inside pre-validation, which is the only place old values are exposed.","Register a pre-image on the step that includes the needed column, and read it from context.PreEntityImages.","Read context.OutputParameters, which always contains the full prior record.","Register a post-image, since post-images capture values before the operation on Update."],"correct":[1],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A pre-image captures the record's values before the operation and is available on Update and Delete; registering it with the required columns lets you read unchanged values that the Target does not include.","source":{"title":"Understand the execution context — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/understand-the-data-context"}},{"id":"gen-149","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A synchronous plug-in registered on the Create message of Order must read the GUID of the newly created row to create a related row. From where and in which stage does it retrieve the new record's id?","options":["From context.InputParameters[\"Target\"].Id in pre-operation, because the id is assigned before validation.","From context.PreEntityImages in pre-validation, which always contains the new id.","From context.OutputParameters[\"id\"] in post-operation, because the id is available only after the record is written.","From context.SharedVariables[\"id\"] in any stage, since Dataverse always populates it."],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"On Create, the new record's Guid is placed in context.OutputParameters[\"id\"] and is available in the post-operation stage after the row has been written.","source":{"title":"Understand the execution context — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/understand-the-data-context"}},{"id":"gen-150","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A synchronous pre-operation plug-in detects that a proposed credit limit exceeds the approved cap and must abort the operation while showing the user a clear message. What should the code do?","options":["Throw InvalidPluginExecutionException with a message, which rolls back the transaction and surfaces the message to the user.","Set context.OutputParameters[\"Cancel\"] to true, which silently discards the operation.","Return without setting the Target, which prevents the write from occurring.","Call ITracingService.Trace with an error string, which stops the pipeline automatically."],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Throwing InvalidPluginExecutionException in a synchronous in-transaction stage rolls back the whole operation and displays the supplied message to the user.","source":{"title":"Use plug-ins to extend business processes — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/plug-ins"}},{"id":"gen-151","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Why must a Dataverse plug-in class be written to be stateless, avoiding instance/member fields that hold per-request data?","options":["Because the sandbox forbids any class from declaring fields.","Because static analysis in the Plug-in Registration Tool rejects assemblies that contain fields.","Because each Execute call creates a brand-new AppDomain that discards fields.","Because Dataverse caches and reuses the IPlugin instance across invocations and threads, so shared fields are not thread-safe."],"correct":[3],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dataverse caches and reuses the IPlugin instance across multiple invocations and threads; storing per-call data in member fields is not thread-safe, so state must be kept in local variables inside Execute.","source":{"title":"Use plug-ins to extend business processes — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/plug-ins"}},{"id":"gen-152","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Inside a plug-in's Execute method you have the IServiceProvider. What is the correct sequence to obtain an IOrganizationService that runs as the initiating user?","options":["Instantiate a new ServiceClient with a connection string, then call its Create method.","Get IOrganizationServiceFactory from the provider, then call factory.CreateOrganizationService(context.UserId).","Cast the IServiceProvider directly to IOrganizationService.","Get IPluginExecutionContext and read its OrganizationService property."],"correct":[1],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"You retrieve IOrganizationServiceFactory from the service provider and call CreateOrganizationService(context.UserId) to get a service that runs in the security context of the initiating user; passing null runs as SYSTEM.","source":{"title":"Understand the execution context — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/understand-the-data-context"}},{"id":"gen-153","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Several apps and server-side components need to invoke a reusable 'RecalculatePricing' operation with typed inputs and outputs, callable from both the Web API and the Organization service and restricted to authorized callers. What should you build?","options":["A synchronous post-operation plug-in step on the Update message of every affected table.","A classic dialog process triggered from a ribbon button.","A custom API that defines the new message with request parameters and response properties, backed by a plug-in and secured with an Execute Privilege.","A cloud flow with an HTTP trigger that runs the pricing logic."],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A custom API is the code-first way to define your own message with typed request parameters and response properties, backed by a plug-in main operation and gated by an Execute Privilege; it is callable from the Web API and Organization service like any built-in message.","source":{"title":"Create and use custom APIs — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/custom-api"}},{"id":"gen-154","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You are defining a custom API that only reads data, has no side effects, and should be invocable with an HTTP GET request. Which custom API setting expresses this?","options":["Set Is Function to true, so the message is exposed as an OData function callable via GET with no side effects.","Set Binding Type to EntityCollection so it becomes read-only.","Set Is Private to true so callers can only use GET.","Set Allowed Custom Processing Step Type to None, which forces GET semantics."],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A custom API with Is Function set to true is exposed as an OData function callable via GET and must not have side effects; when Is Function is false it is an action invoked via POST.","source":{"title":"Create and use custom APIs — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/custom-api"}},{"id":"gen-155","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your organization wants low-code and pro-code consumers to react to meaningful state changes surfaced through a discoverable catalog, and to define custom events and connect external events to decouple producers from consumers. Which Dataverse capability provides this?","options":["Change tracking with delta links.","The audit log and its retention policies.","Server-side synchronization profiles.","Dataverse business events, exposed through the event catalog, including custom events and external events."],"correct":[3],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dataverse business events represent meaningful state changes surfaced through the event catalog; they let both low-code and pro-code consumers react, and support custom events and external events to decouple producers and consumers.","source":{"title":"Dataverse business events — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/business-events"}},{"id":"gen-156","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A plug-in on Update of Account updates the same Account row, which retriggers the step and threatens infinite recursion. Which execution context member helps you detect and guard against this, and at what value does Dataverse abort the chain?","options":["context.Mode, which aborts at value 1.","context.Depth, which increments on each triggered call and causes Dataverse to abort when it reaches 8.","context.Stage, which aborts when it exceeds 40.","context.CorrelationId, which aborts after 8 identical GUIDs."],"correct":[1],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"context.Depth increments each time one plug-in's operation triggers another; Dataverse aborts the chain at depth 8, so checking Depth (or avoiding updating the same row) guards against infinite recursion.","source":{"title":"Understand the execution context — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/understand-the-data-context"}},{"id":"gen-157","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A synchronous plug-in registered on the Update message of Contact runs on every update even when only unrelated columns change, hurting performance. What is the recommended way to make it fire only when specific columns change?","options":["Move the step to asynchronous mode so it never affects update performance.","Add a condition in code that calls RetrieveMultiple to compare all columns.","Register filtering attributes on the step so it executes only when one of the specified columns is included in the update.","Register the step in pre-validation, which automatically limits execution to changed columns."],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Registering filtering attributes on an Update step causes the plug-in to fire only when at least one of the specified columns is part of the update, avoiding needless executions.","source":{"title":"Register a plug-in — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/register-plug-in"}},{"id":"gen-158","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You need to pass a connection secret to a plug-in step so that it is protected and not exposed to users who can merely view the step's configuration. Which mechanism should you use?","options":["The secure configuration string passed to the plug-in constructor, which is protected and not readable by ordinary step viewers.","The unsecure configuration string, because it is encrypted at rest.","A public static field on the plug-in class initialized at registration.","context.SharedVariables, which persists secrets across all steps securely."],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A plug-in step can receive both an unsecure and a secure configuration string in the constructor; the secure string is protected and not readable by users who can only view the step, unlike the unsecure string.","source":{"title":"Register a plug-in — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/register-plug-in"}},{"id":"gen-159","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An online plug-in runs in the sandbox (isolation) mode. Which statement correctly describes a sandbox restriction the developer must design around?","options":["It may write to the local file system but not the registry.","It can run for up to 30 minutes per invocation before timing out.","It may access the Windows event log for logging.","It has no file system, registry, or event log access, allows only outbound network calls, and is limited to a 2-minute execution time."],"correct":[3],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Sandboxed (partial-trust) plug-ins cannot access the file system, registry, or event log; only outbound HTTP/HTTPS network access is allowed, and each invocation is subject to a 2-minute execution limit.","source":{"title":"Use plug-ins to extend business processes — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/plug-ins"}},{"id":"gen-160","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a plug-in registered on the Update message, you read context.InputParameters[\"Target\"] as an Entity. What does this Target contain?","options":["A full snapshot of the record with every attribute populated.","Only the attributes that were changed (included) in the update request.","The record's values as they were before the update.","An EntityReference identifying the row, with no attribute values."],"correct":[1],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"On Update, the Target Entity contains only the attributes included in the request (the changed columns); values not in the request must be read from a pre-image. For Delete the Target is an EntityReference.","source":{"title":"Understand the execution context — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/understand-the-data-context"}},{"id":"gen-161","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A plug-in must perform an operation that a standard user is not allowed to do, so it should run with elevated (SYSTEM) privileges rather than as the calling user. How do you create that IOrganizationService?","options":["Call factory.CreateOrganizationService(context.InitiatingUserId).","Set context.Mode to 1 before creating the service.","Call factory.CreateOrganizationService(null) to run as the SYSTEM user.","Register the step in pre-validation, which always runs as SYSTEM."],"correct":[2],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Passing null to IOrganizationServiceFactory.CreateOrganizationService creates a service that runs as the SYSTEM user with elevated privileges, whereas passing context.UserId runs in the initiating user's security context.","source":{"title":"Understand the execution context — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/understand-the-data-context"}},{"id":"gen-162","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You register a pre-operation step and a post-operation step on the same Create operation and need to pass a computed value from the pre stage to the post stage. Which execution context feature is designed for this?","options":["context.SharedVariables, a collection that carries data between pre and post stages of the same operation (and to child pipelines via ParentContext).","context.OutputParameters, which persists automatically between stages.","A static member field on the plug-in class, which is safe across stages.","context.PreEntityImages, which is the only way to move custom data between stages."],"correct":[0],"skill":5,"sub":"5.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"SharedVariables is a collection on the execution context intended to pass data between the pre-stage and post-stage of the same operation, and can be accessed from a child pipeline through the ParentContext.","source":{"title":"Understand the execution context — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/understand-the-data-context"}},{"id":"gen-163","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You need to create a custom connector so makers can call a third-party REST API from Power Automate and canvas apps. The vendor already publishes a valid OpenAPI (Swagger) 2.0 document that describes every operation, request, and response. Which approach lets you build the connector with the least manual definition work?","options":["Rebuild each operation by hand on the Definition tab because Power Platform ignores imported OpenAPI files","Import the vendor's OpenAPI file when creating the connector so the actions, parameters, and schemas are populated automatically","Convert the OpenAPI file into a Postman collection first, because only Postman collections can be imported","Register the API as an on-premises data gateway resource instead of a custom connector"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A custom connector can be created directly from an OpenAPI definition, which automatically generates the actions, parameters, and response schemas from the imported document, minimizing manual work.","source":{"title":"Create a custom connector from an OpenAPI definition — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/define-openapi-definition"}},{"id":"gen-164","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"While building a custom connector you reach the Security tab. The target REST API requires each request to include a static header named 'x-api-key' whose value the connecting user supplies once when they create a connection. Which authentication type should you select?","options":["API Key","OAuth 2.0","Basic authentication","No authentication"],"correct":[0],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"API Key authentication is used when the service expects a single key (for example in a named header) that the user provides when creating the connection; the connector prompts for it and injects it into each call.","source":{"title":"Custom connectors overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/"}},{"id":"gen-165","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your custom connector must call an API protected by Microsoft Entra ID (Azure AD). The API is registered as an app, and users should sign in interactively so the connector obtains delegated access tokens on their behalf. Which authentication type should you configure on the Security tab?","options":["No authentication","API Key","OAuth 2.0","Basic authentication"],"correct":[2],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"OAuth 2.0 (including the Microsoft Entra ID identity provider option) lets the connector perform an interactive sign-in and obtain access tokens on the user's behalf using the registered app's client ID, secret, and scopes.","source":{"title":"Custom connectors overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/"}},{"id":"gen-166","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You want every request sent by your custom connector to automatically include a static custom header 'x-source: PowerPlatform' without asking each maker to add it and without changing the backend API. You prefer configuration over writing code. What is the best way to achieve this?","options":["Add a required query parameter to every action on the Definition tab","Apply the 'Set HTTP header' policy template on the connector","Write an Azure Function that proxies all traffic and injects the header","Ask each user to type the header value when creating a connection"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Policy templates modify connector behavior at runtime without code; the 'Set HTTP header' policy template injects or overrides a header value on outbound requests for every operation.","source":{"title":"Policy templates for custom connectors — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/policy-templates"}},{"id":"gen-167","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A backend team renamed an API route from '/v1/orders' to '/v2/orders'. You do not want to edit and re-test every action definition in the custom connector. Which policy template lets you rewrite the outbound request path at runtime with the least disruption?","options":["Convert array to CSV","Set query string parameter","Set property","Route request"],"correct":[3],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The 'Route request' policy template rewrites the outbound request URL/path at runtime, so you can redirect calls to the new route without editing each operation definition.","source":{"title":"Policy templates for custom connectors — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/policy-templates"}},{"id":"gen-168","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a custom connector action, a text parameter named 'status' should present users with a fixed dropdown of allowed values (New, Active, Closed) instead of a free-text box. Which OpenAPI extension provides these friendly display values?","options":["x-ms-visibility","x-ms-summary","x-ms-enum-values","x-ms-dynamic-values"],"correct":[2],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The x-ms-enum-values extension supplies a static list of allowed values with display names and values, rendering the parameter as a dropdown of predefined options.","source":{"title":"Extend an OpenAPI definition for a custom connector — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/openapi-extensions"}},{"id":"gen-169","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You are extending a custom connector's OpenAPI definition so that a 'projectId' parameter's dropdown is populated at runtime by calling another operation in the same connector that returns the current list of projects. Which x-ms-* extension should you add to the parameter?","options":["x-ms-dynamic-values","x-ms-trigger","x-ms-notification-content","x-ms-capabilities"],"correct":[0],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"x-ms-dynamic-values populates a parameter's list of selectable options at runtime by invoking a specified operation and mapping its response to display and value fields.","source":{"title":"Extend an OpenAPI definition for a custom connector — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/openapi-extensions"}},{"id":"gen-170","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A custom connector returns a generic 'object' response, so downstream flow steps cannot see individual fields in the dynamic content picker. You want the output schema to be discovered at runtime based on the selected operation. Which OpenAPI extension should you use?","options":["x-ms-summary","x-ms-dynamic-schema","x-ms-visibility","x-ms-url-encoding"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"x-ms-dynamic-schema retrieves the schema of a parameter or response at runtime, so Power Automate can surface the correct fields dynamically in the designer.","source":{"title":"Extend an OpenAPI definition for a custom connector — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/openapi-extensions"}},{"id":"gen-171","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You are exposing an internal REST API built as an HTTP-triggered Azure Function as a custom connector. When defining the connector's Host and Base URL, which value should you supply so that connector operations call the Function correctly?","options":["The storage account connection string of the Function app","The Function app's public HTTPS hostname (for example myapp.azurewebsites.net)","The resource group name that contains the Function","The local development URL http://localhost:7071"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"For an Azure Function-backed connector, the Host is the Function app's public HTTPS hostname (e.g. <app>.azurewebsites.net); the connector's operations map to the Function's HTTP routes.","source":{"title":"Custom connectors overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/"}},{"id":"gen-172","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Within the custom connector wizard, on which tab do you define the connector's actions, request parameters, and response body schemas — for example by using 'Import from sample' to paste a sample request and response?","options":["The General tab","The Security tab","The Definition tab","The Test tab"],"correct":[2],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Definition tab is where actions, triggers, request parameters, and response schemas are configured; 'Import from sample' generates the schema from a pasted sample request/response.","source":{"title":"Create a custom connector from an OpenAPI definition — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/define-openapi-definition"}},{"id":"gen-173","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After creating a custom connector from an OpenAPI file, you open the Test tab to validate an action. Before you can run a test, what must you do first?","options":["Certify the connector through Microsoft's partner program","Create a connection by providing the credentials the connector's security scheme requires","Convert the connector into a managed solution","Publish the connector to the public connector gallery"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Testing an operation requires an active connection; you must create a connection supplying whatever credentials the configured authentication (API key, OAuth, etc.) needs before invoking the test.","source":{"title":"Create a custom connector from an OpenAPI definition — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/define-openapi-definition"}},{"id":"gen-174","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"The API behind your custom connector returns internal diagnostic fields in some responses that should never be sent back to the caller. You want to strip a specific property from the outbound response at runtime without modifying the API. Which policy template is most appropriate?","options":["Set property","Convert array to CSV","Set HTTP header","Set query string parameter"],"correct":[0],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The 'Set property' policy template can add, update, or remove a property in the request or response body at runtime, allowing you to remove an unwanted field without changing the backend.","source":{"title":"Policy templates for custom connectors — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/policy-templates"}},{"id":"gen-175","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A parameter in your custom connector action is technically required by the API but should be hidden from normal makers and only shown to advanced users. Which OpenAPI extension controls whether the field appears prominently, in the advanced section, or is hidden in the designer?","options":["x-ms-dynamic-values","x-ms-trigger","x-ms-notification-url","x-ms-visibility"],"correct":[3],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"x-ms-visibility controls a property's display state in the designer with values 'important', 'advanced', or 'internal' (hidden), letting you tuck away parameters that most users should not set.","source":{"title":"Extend an OpenAPI definition for a custom connector — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/openapi-extensions"}},{"id":"gen-176","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You want your custom connector to expose a trigger so that a cloud flow can start when the external service posts an event to a callback URL that the connector registers. Which OpenAPI extension identifies the operation as this kind of subscription-based trigger?","options":["x-ms-summary with a polling interval","x-ms-trigger set to 'single' with x-ms-notification-content for a webhook trigger","x-ms-enum-values listing event types","x-ms-url-encoding set to 'double'"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Marking an operation with x-ms-trigger (and providing x-ms-notification-content for the callback payload) defines a webhook-style trigger, so the service notifies the connector's registered callback URL rather than being polled.","source":{"title":"Extend an OpenAPI definition for a custom connector — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/openapi-extensions"}},{"id":"gen-177","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your organization wants a reusable custom connector defined in code and deployed through source control and CI/CD, rather than clicking through the portal wizard each time. Which tooling directly supports creating and updating custom connectors from their definition files?","options":["The Plug-in Registration Tool","The Configuration Migration tool","Power BI Report Builder","The Power Apps CLI 'paconn' tool (Power Platform Connectors CLI)"],"correct":[3],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Power Platform Connectors CLI (paconn) lets you download, create, and update custom connectors from their API definition, properties, and icon files, enabling source control and automated deployment.","source":{"title":"Custom connectors overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/"}},{"id":"gen-178","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A custom connector action sends an array parameter, but the backend API expects those values as a single comma-separated query string. You want to reshape the outbound data at runtime using configuration. Which policy template fits?","options":["Route request","Set HTTP header","Convert array to CSV","Set property"],"correct":[2],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The 'Convert array to CSV' policy template transforms an array into a comma-separated values string at runtime, matching APIs that expect delimited query parameters.","source":{"title":"Policy templates for custom connectors — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/policy-templates"}},{"id":"gen-179","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You have an OpenAPI file that describes the REST API, but its host points to a staging environment. Before importing it to create the production custom connector, what is the correct place to correct the host and base path?","options":["You cannot change it; the connector is permanently bound to whatever host is in the file","Edit the host/base URL on the General tab of the connector after import","Only by editing the API's DNS records","By re-registering the API in the on-premises data gateway"],"correct":[1],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"After importing an OpenAPI definition, the General tab exposes the Host and Base URL, which you can edit to point the connector at the correct (production) endpoint.","source":{"title":"Create a custom connector from an OpenAPI definition — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/define-openapi-definition"}},{"id":"gen-180","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You give a request parameter a technical name of 'proj_id' in the API, but you want makers to see the friendly label 'Project ID' in the Power Automate and canvas app designer. Which OpenAPI extension sets that human-readable title on the parameter?","options":["x-ms-summary","x-ms-visibility","x-ms-dynamic-schema","x-ms-capabilities"],"correct":[0],"skill":5,"sub":"5.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"x-ms-summary provides the user-friendly display title for a parameter or operation shown in the designer, independent of the underlying technical property name.","source":{"title":"Extend an OpenAPI definition for a custom connector — Microsoft Learn","url":"https://learn.microsoft.com/en-us/connectors/custom-connectors/openapi-extensions"}},{"id":"gen-181","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer is building a client-side JavaScript web resource that must create and retrieve Dataverse rows directly from the browser without any .NET runtime. Which Dataverse API should be used?","options":["The Organization service through the IOrganizationService interface","The TDS (Tabular Data Stream) SQL read-only endpoint","The Dataverse Web API, an OData v4 RESTful endpoint","The legacy 2011 SOAP endpoint referenced from the web resource"],"correct":[2],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Dataverse Web API is an OData v4 RESTful endpoint usable from any language or platform, including browser JavaScript, without needing the .NET SDK assemblies that IOrganizationService requires.","source":{"title":"Use the Dataverse Web API — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/webapi/overview"}},{"id":"gen-182","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A .NET plug-in and a console integration app both need strongly typed access to Dataverse messages such as CreateRequest and RetrieveMultipleRequest. Which interface do they use to invoke these messages?","options":["IOrganizationService, the core interface of the SDK for .NET","IPluginExecutionContext, called directly to run messages","HttpClient configured against the OData $metadata document","IOrganizationServiceFactory returned to the caller as the message channel"],"correct":[0],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The SDK for .NET exposes IOrganizationService, whose Execute method (and helper methods) processes message request classes like CreateRequest and RetrieveMultipleRequest against Dataverse.","source":{"title":"Use the SDK for .NET — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/org-service/overview"}},{"id":"gen-183","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An integration hitting Dataverse in a tight loop suddenly starts receiving errors once it exceeds the service protection thresholds. Which HTTP status code indicates the request was throttled by service protection limits?","options":["503 Service Unavailable","429 Too Many Requests","403 Forbidden","408 Request Timeout"],"correct":[1],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"When service protection API limits are exceeded, Dataverse returns HTTP 429 (Too Many Requests) so clients can back off and retry.","source":{"title":"Service protection API limits — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/api-limits"}},{"id":"gen-184","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After receiving a 429 response from Dataverse, what is the recommended way for a well-behaved client to decide how long to wait before retrying?","options":["Retry immediately in a loop until the request succeeds","Wait a fixed 60 seconds regardless of the response","Open a second connection to spread the load across servers","Honor the Retry-After header value returned with the 429 response"],"correct":[3],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A 429 response includes a Retry-After header specifying the number of seconds to wait; clients should pause for that duration before retrying rather than retrying immediately.","source":{"title":"Service protection API limits — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/api-limits"}},{"id":"gen-185","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer needs to submit hundreds of independent create operations to Dataverse in as few round trips as possible, and wants processing to continue even if some rows fail. Which message is most appropriate?","options":["ExecuteTransactionRequest, so a single failure rolls everything back","A separate Create call per row wrapped in a database transaction scope","ExecuteMultipleRequest with ContinueOnError set to true","UpsertRequest issued once with all rows in a single payload"],"correct":[2],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"ExecuteMultipleRequest batches many message requests into one round trip; setting ContinueOnError to true lets processing proceed past individual failures. It is not transactional, which suits independent operations.","source":{"title":"Use the SDK for .NET — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/org-service/overview"}},{"id":"gen-186","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A set of related writes must all succeed or all be rolled back together as a single atomic unit of work. Which Dataverse message provides this behavior?","options":["ExecuteTransactionRequest, which runs the requests in one database transaction","ExecuteMultipleRequest with ReturnResponses set to true","A batch of individual Web API POST calls sent in parallel","RetrieveMultipleRequest with a locking hint applied"],"correct":[0],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"ExecuteTransactionRequest executes its collection of requests within a single database transaction, so if any request fails the entire set is rolled back, guaranteeing all-or-nothing behavior.","source":{"title":"Use the SDK for .NET — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/org-service/overview"}},{"id":"gen-187","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A background service (daemon) with no interactive user must authenticate to Dataverse using its own identity. Which OAuth approach should be configured?","options":["Prompt the user for their Dataverse username and password at startup","Use a shared read-only anonymous endpoint that needs no token","Embed a static Web API key in the connection string","Register an app in Microsoft Entra ID and connect as an application using the client credentials flow"],"correct":[3],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"For server-to-server (S2S) scenarios, you register an application in Microsoft Entra ID and connect as an app using the client credentials flow (client ID plus secret or certificate), with no interactive user involved.","source":{"title":"Use OAuth authentication with Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/authenticate-oauth"}},{"id":"gen-188","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which library does Microsoft recommend for acquiring OAuth tokens when authenticating custom code to the Dataverse Web API?","options":["The deprecated Azure AD Authentication Library (ADAL)","The Microsoft Authentication Library (MSAL)","Basic authentication over HTTPS with a base64-encoded header","A manually crafted SAML assertion posted to the token endpoint"],"correct":[1],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Dataverse requires OAuth, and Microsoft recommends the Microsoft Authentication Library (MSAL) to obtain the bearer tokens used to authenticate requests to the Web API.","source":{"title":"Use OAuth authentication with Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/authenticate-oauth"}},{"id":"gen-189","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants to group several Web API create and update operations into one HTTP request to reduce network overhead. Which Web API feature enables this?","options":["Repeated calls to the $metadata endpoint","The $expand query option on each individual request","The $batch operation, which sends multiple operations in a single request","The Prefer: odata.include-annotations request header"],"correct":[2],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Dataverse Web API supports the OData $batch operation, letting a client combine multiple operations, optionally within change sets, into a single HTTP request.","source":{"title":"Use the Dataverse Web API — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/webapi/overview"}},{"id":"gen-190","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Service protection limits evaluate client activity over a sliding five-minute window per web server. Which three measures do these limits track?","options":["Total storage consumed, number of tables, and plug-in step count","API version, payload size, and column count returned","Row count, relationship depth, and query timeout","Number of requests, combined execution time, and number of concurrent requests"],"correct":[3],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Service protection limits are based on three measures per server over a five-minute window: the number of requests, the combined execution (processing) time of those requests, and the number of concurrent requests.","source":{"title":"Service protection API limits — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/api-limits"}},{"id":"gen-191","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A bulk import routine sends thousands of unrelated row creates. The developer wants maximum throughput and does NOT need the operations to share a transaction. Which choice best fits?","options":["ExecuteMultipleRequest, which batches requests without wrapping them in a transaction","ExecuteTransactionRequest, so a mid-batch failure undoes prior successes","One ExecuteTransactionRequest per row to isolate failures","A single AssociateRequest carrying all the new rows"],"correct":[0],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"ExecuteMultipleRequest optimizes network performance by batching many requests in one round trip and is not transactional, which is ideal when the operations are independent and should not roll each other back.","source":{"title":"Use the SDK for .NET — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/org-service/overview"}},{"id":"gen-192","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An integration is frequently hitting the concurrent-request service protection limit. Which strategy is recommended to reduce 429 throttling?","options":["Increase the number of parallel threads to finish the work faster","Reduce the number of concurrent connections/threads and apply exponential backoff on retries","Disable the Retry-After header handling to avoid delays","Switch every request to synchronous mode to serialize on the server"],"correct":[1],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Microsoft recommends lowering the degree of parallelism (fewer concurrent threads/connections) and using exponential backoff that honors Retry-After, rather than adding more threads, which worsens throttling.","source":{"title":"Service protection API limits — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/api-limits"}},{"id":"gen-193","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After registering an Entra ID app for server-to-server access, a daemon still receives authorization errors from Dataverse even though the token is valid. What additional Dataverse configuration is required?","options":["Enable the legacy SOAP endpoint for the environment","Add the app's client secret to every Web API request header","Create an application user in the Dataverse environment and assign it a security role","Grant the app the global administrator role in Microsoft 365"],"correct":[2],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"For S2S connections, the registered app must be mapped to an application user in the target Dataverse environment and that application user must be assigned a security role granting the needed privileges.","source":{"title":"Use OAuth authentication with Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/authenticate-oauth"}},{"id":"gen-194","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A Web API client must avoid overwriting a row that another user has changed since it was last read. Which mechanism supports this optimistic concurrency control?","options":["Adding a $top=1 query option to serialize writes","Setting the Prefer: return=representation header","Wrapping each PATCH in its own $batch change set","Sending the row's ETag in an If-Match header on the update request"],"correct":[3],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Web API supports optimistic concurrency using ETags: the client sends the previously retrieved ETag in an If-Match header, and Dataverse rejects the update if the row has changed, preventing lost updates.","source":{"title":"Use the Dataverse Web API — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/webapi/overview"}},{"id":"gen-195","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In current .NET SDK development, which class is recommended to connect to Dataverse and obtain an IOrganizationService instance?","options":["ServiceClient from the Microsoft.PowerPlatform.Dataverse.Client package","The deprecated CrmServiceClient from the legacy XRM tooling assembly","OrganizationServiceProxy created with explicit SOAP bindings","A raw HttpClient wrapped in a custom IOrganizationService adapter"],"correct":[0],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The ServiceClient class in Microsoft.PowerPlatform.Dataverse.Client is the current recommended way to connect to Dataverse and implements IOrganizationService, replacing the older CrmServiceClient.","source":{"title":"Use the SDK for .NET — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/org-service/overview"}},{"id":"gen-196","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer is deciding between ExecuteMultiple and ExecuteTransaction for a batch that mixes several updates that logically belong together. Which statement correctly distinguishes them?","options":["Both roll back automatically when any single request fails","ExecuteTransaction runs all requests in one transaction so a failure rolls back the batch, while ExecuteMultiple does not","ExecuteMultiple guarantees ordering and atomicity; ExecuteTransaction does not","ExecuteMultiple can only contain retrieve requests, never writes"],"correct":[1],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"ExecuteTransactionRequest wraps its requests in a single database transaction (all-or-nothing), whereas ExecuteMultipleRequest simply batches requests for network efficiency and is not transactional.","source":{"title":"Use the SDK for .NET — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/org-service/overview"}},{"id":"gen-197","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A resilient client catches a 429 and reads the Retry-After header. What does the value of that header represent?","options":["The maximum number of rows the next request may return","The remaining request quota for the five-minute window","The number of seconds to wait before sending the next request","The server timestamp at which the throttle was first triggered"],"correct":[2],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Retry-After header on a 429 response gives the number of seconds the client should wait before retrying the request.","source":{"title":"Service protection API limits — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/api-limits"}},{"id":"gen-198","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An external application calls the Dataverse Web API over HTTPS. How must it present its identity on each request?","options":["By including a shared environment API key as a query string parameter","By using HTTP Basic authentication with the maker's credentials","By passing the environment's client secret directly in a custom header","By sending an OAuth 2.0 bearer access token in the Authorization header"],"correct":[3],"skill":5,"sub":"5.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Dataverse Web API requires OAuth 2.0; the client acquires an access token (for example via MSAL) and sends it as a bearer token in the Authorization header of each request.","source":{"title":"Use OAuth authentication with Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/authenticate-oauth"}},{"id":"gen-199","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A Dataverse plug-in must call a third-party pricing engine that frequently takes 30-90 seconds to respond. The synchronous plug-in pipeline enforces a 2-minute limit and blocks the user's transaction. What is the most appropriate way to offload this long-running computation?","options":["Increase the plug-in step's execution timeout in the Plug-in Registration Tool","Move the call into an Azure Function invoked from an asynchronous process, letting the serverless platform run the long operation outside the Dataverse transaction","Wrap the call in a Power Fx formula on the form's OnLoad event","Run the pricing call inside a synchronous pre-validation plug-in step"],"correct":[1],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Functions is a serverless compute service designed for event-driven and long-running background workloads, so offloading the slow external call to a Function keeps it out of the blocking Dataverse synchronous pipeline. Extending timeouts or running it synchronously would still block the user's transaction.","source":{"title":"Azure Functions overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview"}},{"id":"gen-200","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your team wants to build small pieces of event-driven code that scale automatically and are billed only for the compute time actually consumed, without provisioning or managing servers. Which Azure service best matches this serverless model?","options":["Azure Functions","Azure Virtual Machines","Azure App Service Environment (dedicated)","Azure Batch dedicated pools"],"correct":[0],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Functions is Microsoft's serverless compute offering: you write focused functions that run in response to events and, on the Consumption plan, are billed based on resource consumption and executions rather than pre-provisioned servers.","source":{"title":"Azure Functions overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview"}},{"id":"gen-201","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer is deciding whether Azure Functions is a good fit for a workload that ingests messages from a queue, processes each message, and writes results elsewhere. Which characteristic of Azure Functions most directly supports this scenario?","options":["Functions require you to manage the underlying operating system patching","Functions can only be triggered manually from a portal button","Functions run code in response to events such as messages arriving, and scale out based on demand","Functions must run continuously as a always-on monolithic web application"],"correct":[2],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Functions executes code in response to triggering events (like a queue message) and scales automatically with load, which is exactly the event-driven, per-message processing pattern the scenario describes.","source":{"title":"Azure Functions overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview"}},{"id":"gen-202","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You need an Azure Function to run automatically at a fixed schedule, for example every night at 2:00 AM, to purge stale integration records. Which trigger type should the function use?","options":["An HTTP trigger polled by a client every minute","A blob trigger on an unused container","A manual trigger started from the Azure portal","A timer trigger configured with a schedule expression"],"correct":[3],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The timer trigger runs a function on a defined schedule (using a CRON-style expression), which is the standard binding for recurring, time-based jobs in Azure Functions.","source":{"title":"Triggers and bindings in Azure Functions — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-triggers-bindings"}},{"id":"gen-203","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Azure Functions, what is the fundamental difference between a trigger and a binding?","options":["A trigger defines how a function is invoked, while a binding declaratively connects another resource as input or output data","A trigger and a binding are identical and interchangeable terms","A binding starts execution of the function, while a trigger only formats the log output","A trigger can only be HTTP, while a binding can only be a timer"],"correct":[0],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Every function has exactly one trigger that causes it to run, whereas bindings are a declarative way to connect input and output data (such as a storage queue or table) without writing SDK plumbing code. A function can have multiple input and output bindings.","source":{"title":"Triggers and bindings in Azure Functions — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-triggers-bindings"}},{"id":"gen-204","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An Azure Function should execute whenever an external system posts JSON to a public endpoint, returning a response to the caller. Which trigger is appropriate?","options":["A timer trigger","A Service Bus queue trigger","An HTTP trigger","A Cosmos DB change feed trigger"],"correct":[2],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An HTTP trigger runs the function in response to an incoming HTTP request and can return an HTTP response to the caller, which fits a request/response REST endpoint scenario.","source":{"title":"Triggers and bindings in Azure Functions — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-triggers-bindings"}},{"id":"gen-205","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A function needs to write its output to an Azure Storage queue when it finishes. Rather than instantiating and authenticating a storage client in code, the developer wants a declarative approach. What should they use?","options":["A second trigger on the same function","A managed identity role assignment only","A custom connector policy template","An output binding to the storage queue"],"correct":[3],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Output bindings let a function send data to another service declaratively, avoiding hand-written SDK code for connecting and authenticating. Each function has one trigger but can declare multiple input and output bindings.","source":{"title":"Triggers and bindings in Azure Functions — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-triggers-bindings"}},{"id":"gen-206","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An Azure Function running under an App Service plan must call Azure Key Vault to retrieve a secret. The team wants to avoid storing any client secret or connection string in configuration. Which approach eliminates managing credentials in code or settings?","options":["Hard-code a shared access signature token in the function's app settings","Enable a managed identity for the function and grant it access to Key Vault","Store the Key Vault master key inside the function's source code","Embed a service principal password in an environment variable"],"correct":[1],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A managed identity provides an automatically managed identity in Microsoft Entra ID that services use to authenticate to resources supporting Entra authentication, so no credentials are stored in code or configuration.","source":{"title":"Managed identities for Azure resources overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview"}},{"id":"gen-207","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"What is a key advantage of using a system-assigned managed identity for an Azure resource that authenticates to other Azure services?","options":["It requires developers to rotate the secret manually every 90 days","It works only for on-premises Active Directory, not Microsoft Entra ID","It exposes the credential in the resource's public metadata for easy sharing","There are no credentials to manage; the identity's lifecycle is tied to the resource and credentials are handled by the platform"],"correct":[3],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"System-assigned managed identities are created and deleted along with the Azure resource, and the platform manages the credentials, so developers never handle or rotate secrets themselves.","source":{"title":"Managed identities for Azure resources overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview"}},{"id":"gen-208","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A single Azure Function app should share one identity that persists even if the app is deleted and recreated, and the same identity must be assigned to several other resources. Which managed identity type fits?","options":["A user-assigned managed identity","A system-assigned managed identity","A self-signed X.509 certificate stored in code","An account access key rotated by hand"],"correct":[0],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A user-assigned managed identity is created as a standalone Azure resource with its own lifecycle and can be assigned to multiple resources, so it survives independently of any single resource and can be shared.","source":{"title":"Managed identities for Azure resources overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview"}},{"id":"gen-209","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You are building a cloud flow that must react to business data changes in Dataverse and also perform create, update, and retrieve operations on Dataverse rows. Which connector should the flow use for the most native, performant integration?","options":["The generic HTTP connector calling the Web API manually","The Microsoft Dataverse connector","The SharePoint connector","The Azure Blob Storage connector"],"correct":[1],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Microsoft Dataverse connector provides native triggers and actions for reacting to and operating on Dataverse data in Power Automate, giving richer and more efficient integration than hand-built HTTP calls.","source":{"title":"Integrate flows with Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/dataverse/overview"}},{"id":"gen-210","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A flow using the Dataverse connector needs to run only in the context of a specific Dataverse environment's tables and take advantage of features like row images and filtered triggers. Which connector capability supports building event-driven automation on Dataverse rows?","options":["The connector offers only manual button triggers","The connector can only send email, not query tables","The connector requires exporting data to Excel first","The connector provides triggers such as when a row is added, modified, or deleted, plus actions to work with rows"],"correct":[3],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Dataverse connector exposes row-based triggers (added, modified, deleted) and corresponding actions, which is the foundation for event-driven flows that respond to data changes in a Dataverse environment.","source":{"title":"Integrate flows with Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/dataverse/overview"}},{"id":"gen-211","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A cloud flow should start only when the Status Reason column of an Account row changes to Active, and it should ignore all other updates to unrelated columns. Which configuration of the 'When a row is added, modified or deleted' trigger achieves this efficiently?","options":["Add a Condition action after the trigger that terminates the flow when the value is not Active","Use the trigger's filter columns and a trigger condition (filter expression) so the trigger fires only for the relevant column and value","Set the flow to run on a 15-minute recurrence and query all accounts each time","Disable the trigger and rely on a manual button"],"correct":[1],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Setting Select columns (filter columns) restricts firing to changes on specific columns, and a trigger condition (filter expression) prevents unnecessary runs, so the flow starts only when the target column reaches the desired value—far more efficient than running and then terminating.","source":{"title":"When a row is added, modified or deleted trigger — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/dataverse/create-update-delete-trigger"}},{"id":"gen-212","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the Dataverse 'When a row is added, modified or deleted' trigger, what is the purpose of the Filter rows (trigger condition) option expressed with an OData-style expression?","options":["It renames the columns returned to the flow","It deletes rows that do not match the expression","It defines a condition that must be true for the trigger to fire, reducing unnecessary flow runs","It changes the run-as user for the flow"],"correct":[2],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Filter rows expression is a trigger condition: the flow only runs when the condition evaluates to true, which prevents the flow from firing (and consuming runs) on changes that are not relevant.","source":{"title":"When a row is added, modified or deleted trigger — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/dataverse/create-update-delete-trigger"}},{"id":"gen-213","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A maker configures the Dataverse row trigger with Change type set to 'Modified' and specifies a Scope. What does the Scope setting control?","options":["The maximum number of rows the flow can create","The retry policy for failed actions","The Azure region where the flow executes","Which rows the trigger monitors based on ownership—such as User, Business Unit, or Organization"],"correct":[3],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Scope property determines the ownership boundary of rows the trigger listens to (for example User, Business Unit, Parent: Child Business Units, or Organization), controlling which changed rows can start the flow.","source":{"title":"When a row is added, modified or deleted trigger — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-automate/dataverse/create-update-delete-trigger"}},{"id":"gen-214","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A cloud flow and a custom connector both need an API key that must not be stored as plain text in the solution. The organization already keeps the key in Azure Key Vault. What is the recommended Power Platform mechanism to reference that secret from a solution-aware flow?","options":["Paste the secret directly into a Compose action","Use an environment variable that references the Azure Key Vault secret","Store the secret in a hidden text column on a Dataverse table","Hard-code the secret into the flow's trigger condition"],"correct":[1],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power Platform supports environment variables that reference Azure Key Vault secrets, so flows and connectors retrieve the secret securely at runtime without embedding it in the solution, and it can differ per environment.","source":{"title":"Use environment variables for Azure Key Vault secrets — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/environmentvariables-azure-key-vault-secrets"}},{"id":"gen-215","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Before a Power Platform environment variable can reference an Azure Key Vault secret, which prerequisite must be satisfied on the Key Vault side?","options":["The Dataverse service principal must be granted access to read the secret, and the vault configured to allow it","The secret must be exported to a CSV file first","The Key Vault must be deleted and recreated in the Dataverse region","The secret value must be shorter than eight characters"],"correct":[0],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"To use a Key Vault secret from a Power Platform environment variable, the Dataverse service principal must be granted read access to the secret and the vault must be configured to permit that access; only then can flows resolve the secret at runtime.","source":{"title":"Use environment variables for Azure Key Vault secrets — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/environmentvariables-azure-key-vault-secrets"}},{"id":"gen-216","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Why is referencing an Azure Key Vault secret through an environment variable preferable to storing the secret value in a standard text environment variable when moving a solution across Dev, Test, and Production?","options":["Text environment variables cannot be added to solutions at all","Key Vault secrets are always identical in every environment and cannot be changed","Only the reference (vault and secret name) travels with the solution while the actual secret stays protected in Key Vault, and each environment can point to its own value","Text environment variables automatically encrypt themselves with no configuration"],"correct":[2],"skill":5,"sub":"5.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A Key Vault-backed environment variable stores only a secure reference in the solution, keeping the secret material in Key Vault and letting each environment resolve its own secret, which is safer and more portable than placing raw secret text in a solution.","source":{"title":"Use environment variables for Azure Key Vault secrets — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/maker/data-platform/environmentvariables-azure-key-vault-secrets"}},{"id":"gen-217","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer must push Dataverse create and update events to an external system that already has an Azure Service Bus queue, with the external application polling the queue on its own schedule. Which service endpoint contract should be registered so messages are simply dropped into the existing queue?","options":["Queue","Two-way (REST)","Topic","Persistent (REST)"],"correct":[0],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Queue contract writes the Dataverse execution context to an Azure Service Bus queue where an external listener retrieves it asynchronously; it does not return data to the platform. Two-way and REST contracts expect a response, and Topic uses publish/subscribe.","source":{"title":"Azure Service Bus integration for Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/azure-integration"}},{"id":"gen-218","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a custom Azure-aware plug-in that posts the execution context to a registered Azure Service Bus endpoint, which interface must the plug-in obtain from the service provider to send the notification?","options":["IOrganizationService","ITracingService","IServiceEndpointNotificationService","IPluginExecutionContext"],"correct":[2],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A custom Azure-aware plug-in retrieves IServiceEndpointNotificationService from the service provider and calls its Execute method, passing the ServiceEndpoint ID, to post the context to Azure Service Bus.","source":{"title":"Write a custom Azure-aware plug-in — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/write-custom-azure-aware-plugin"}},{"id":"gen-219","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants an external REST endpoint (not an Azure messaging service) to receive Dataverse events, and they need to secure the call with either an authentication header or a query-string key. Which integration mechanism fits this requirement?","options":["Azure Service Bus topic subscription","A webhook registered as a service endpoint","Azure Event Hub streaming endpoint","A real-time workflow with an external assembly"],"correct":[1],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Webhooks let Dataverse call an external HTTPS service and support authentication using either an HTTP header or a query-string key. Service Bus and Event Hub are Azure messaging services, not arbitrary REST endpoints.","source":{"title":"Use webhooks — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-webhooks"}},{"id":"gen-220","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement correctly contrasts webhooks with Azure Service Bus integration for consuming Dataverse events?","options":["Webhooks always run asynchronously, while Service Bus can run synchronously","Both webhooks and Service Bus require the external system to run inside Azure","Neither webhooks nor Service Bus can receive the plug-in execution context","Webhooks can execute synchronously and are limited to a single subscriber per operation, while Service Bus supports multiple asynchronous readers"],"correct":[3],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Webhooks support synchronous or asynchronous steps but deliver to one endpoint (single subscriber), whereas Azure Service Bus is asynchronous only and lets multiple listeners retrieve messages. Both convey the execution context.","source":{"title":"Use webhooks — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-webhooks"}},{"id":"gen-221","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A high-volume telemetry scenario needs Dataverse operation events streamed to many downstream consumers for analytics and event processing at scale. Which Azure endpoint type is designed for this big-data event streaming pattern?","options":["Azure Service Bus queue","Webhook","Two-way Service Bus endpoint","Azure Event Hub"],"correct":[3],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Event Hub is a big-data streaming platform suited to ingesting large volumes of events for many consumers, which matches high-throughput telemetry and analytics scenarios.","source":{"title":"Work with event data in an Azure Event Hub solution — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/work-event-data-azure-event-hub-solution"}},{"id":"gen-222","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When registering a service endpoint step that runs synchronously (for example a webhook), what happens to the Dataverse operation if the external listener returns an error or exception?","options":["The operation completes and the error is logged silently","The message is automatically retried up to the Service Bus dead-letter limit","The step is converted to asynchronous and queued","The core operation is rolled back and the exception is surfaced to the user"],"correct":[3],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A synchronous service endpoint step runs within the transaction, so a failure from the external listener rolls back the operation and returns the exception to the caller. Asynchronous steps do not affect the originating transaction this way.","source":{"title":"Use webhooks — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-webhooks"}},{"id":"gen-223","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which tool is used to register a service endpoint (webhook, Azure Service Bus, or Event Hub) and add the step that posts the Dataverse execution context to it?","options":["Power Platform CLI solution import","The Plug-in Registration Tool","Azure Portal Event Grid blade","The Configuration Migration Tool"],"correct":[1],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Plug-in Registration Tool is used to register service endpoints and webhooks and to configure the steps that send the execution context to Azure messaging services or external handlers.","source":{"title":"Azure Service Bus integration for Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/azure-integration"}},{"id":"gen-224","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An integration requires Dataverse to send an event to an external service and receive information back that influences the same operation before it completes. Which Azure Service Bus contract supports returning data to the platform?","options":["One-way (queue)","Topic","Two-way","Event Hub"],"correct":[2],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Two-way contract allows the listener to return a string value back to Dataverse; it must be registered on a synchronous step. One-way/queue and topic contracts do not return data.","source":{"title":"Azure Service Bus integration for Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/azure-integration"}},{"id":"gen-225","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A webhook endpoint receives the Dataverse event. In what format is the RemoteExecutionContext delivered to the external webhook handler?","options":["A JSON payload in the HTTP request body","A serialized .NET binary stream","An XML SOAP envelope","A protobuf message on a Service Bus queue"],"correct":[0],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Webhooks POST the RemoteExecutionContext to the external endpoint as JSON in the request body, so the external handler parses JSON rather than the .NET-serialized message used by Service Bus listeners.","source":{"title":"Use webhooks — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-webhooks"}},{"id":"gen-226","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer registers an asynchronous Azure Service Bus step. Where in the event execution pipeline must asynchronous service endpoint steps be registered?","options":["Pre-validation stage","Pre-operation stage","Post-operation stage","Any stage, synchronous or asynchronous"],"correct":[2],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Asynchronous service endpoint (Azure-aware) steps must be registered in the post-operation stage, because the message is queued by the asynchronous service after the core operation completes.","source":{"title":"Azure Service Bus integration for Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/azure-integration"}},{"id":"gen-227","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"For a fire-and-forget scenario where Dataverse posts events to Azure Service Bus and the platform must never block or wait for the external listener, which listening/registration model should be used?","options":["A synchronous two-way endpoint","A synchronous webhook step","A synchronous custom Azure-aware plug-in","An asynchronous one-way (queue) endpoint"],"correct":[3],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An asynchronous one-way queue endpoint decouples Dataverse from the listener; the system asynchronous service posts the message and does not wait for or depend on the external consumer.","source":{"title":"Azure Service Bus integration for Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/azure-integration"}},{"id":"gen-228","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When using out-of-the-box Azure Service Bus integration (registering a service endpoint step without custom code), what does Dataverse post to the queue or topic?","options":["The full serialized execution context (RemoteExecutionContext)","Only the primary entity's GUID","A summary email notification","The raw SQL change record"],"correct":[0],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Azure integration posts the serialized RemoteExecutionContext (the execution context including input parameters and images) to the messaging endpoint so external listeners can process the event.","source":{"title":"Azure Service Bus integration for Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/azure-integration"}},{"id":"gen-229","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A custom Azure-aware plug-in calls IServiceEndpointNotificationService.Execute and needs to identify which registered service endpoint to post to. What value must be passed to identify the endpoint?","options":["The endpoint's connection string","The ServiceEndpoint record's ID (EntityReference)","The Azure subscription ID","The plug-in step's SdkMessageProcessingStepId"],"correct":[1],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The plug-in passes the ServiceEndpoint ID (as an EntityReference) to IServiceEndpointNotificationService.Execute so Dataverse knows which registered endpoint should receive the posted context.","source":{"title":"Write a custom Azure-aware plug-in — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/write-custom-azure-aware-plugin"}},{"id":"gen-230","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which scenario is the best fit for choosing a webhook over Azure Service Bus for consuming Dataverse events?","options":["Streaming millions of events per minute to a data lake","Buffering events for a consumer that is frequently offline","Fan-out delivery to many independent subscribers","Synchronously calling an external HTTPS API and needing to influence the transaction in near real time"],"correct":[3],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Webhooks can run synchronously and call an external HTTPS service in real time, allowing the operation to be affected by the outcome. Buffering for offline consumers and fan-out suit Service Bus; massive streaming suits Event Hub.","source":{"title":"Use webhooks — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-webhooks"}},{"id":"gen-231","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A consumer application needs to read Dataverse events from an Azure Event Hub. Which client component does the external solution use to consume the streamed event data?","options":["An Event Hub consumer (event processor/receiver) client","A Service Bus QueueClient","An IOrganizationService proxy","A webhook HTTP listener"],"correct":[0],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Event Hub events are read using an Event Hub consumer/receiver (event processor host) client that pulls the streamed messages; Service Bus clients and IOrganizationService are for different integration paths.","source":{"title":"Work with event data in an Azure Event Hub solution — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/work-event-data-azure-event-hub-solution"}},{"id":"gen-232","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Why must the Two-way and REST Service Bus contracts be registered on synchronous steps rather than asynchronous ones?","options":["Because Azure only accepts synchronous TLS connections","Because they return a value to Dataverse, which requires the operation to still be in progress","Because asynchronous steps cannot access Pre-images","Because the asynchronous service does not support authentication"],"correct":[1],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Two-way and REST contracts return data back to the platform, so the originating operation must still be executing to receive it; that requires a synchronous step. One-way/queue/topic contracts, which return nothing, can be asynchronous.","source":{"title":"Azure Service Bus integration for Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/azure-integration"}},{"id":"gen-233","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants downstream systems to subscribe independently to Dataverse events using a publish/subscribe model on Azure Service Bus, where each subscription filters and receives its own copy. Which contract should be registered?","options":["Queue","Two-way","Topic","Persistent"],"correct":[2],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Topic contract implements publish/subscribe: multiple subscriptions can independently receive and filter copies of the posted message, unlike a single-reader queue.","source":{"title":"Azure Service Bus integration for Dataverse — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/azure-integration"}},{"id":"gen-234","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A webhook step is registered asynchronously in the post-operation stage. What is the primary consequence for the external handler compared with a synchronous registration?","options":["The handler receives XML instead of JSON","The handler runs in the system async queue and cannot roll back the originating operation","The handler must return a value or the operation fails","The handler is limited to read-only access to the context"],"correct":[1],"skill":6,"sub":"6.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An asynchronous webhook step is processed by the system asynchronous service after the operation commits, so a failure or delay in the external handler does not roll back or block the original transaction.","source":{"title":"Use webhooks — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-webhooks"}},{"id":"gen-235","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You must build a nightly job that pushes only the Dataverse account rows that changed since the last run to an external data warehouse. Which approach minimizes the volume of data retrieved on each run?","options":["Enable change tracking on the Account table and use the delta token from the previous run to retrieve only changed rows","Query all accounts each run with a filter on the modifiedon column greater than yesterday's date","Register a synchronous post-operation plug-in on Update and write each row to the warehouse inline","Use RetrieveMultiple with paging and compare every column against a local copy"],"correct":[0],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Change tracking lets you request only the data that changed since the last synchronization by passing the delta token (deltalink) from the prior request, avoiding a full extract each time.","source":{"title":"Use change tracking to synchronize data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-change-tracking-synchronize-data-external-systems"}},{"id":"gen-236","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Before you can use change tracking to synchronize a Dataverse table with an external system, what must be true for that table?","options":["The table must be an activity table","The table must have auditing turned off","The table must be configured as a virtual table","The table must have change tracking enabled in its settings"],"correct":[3],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Change tracking is a per-table feature that must be explicitly enabled (via the table's settings/metadata) before delta queries can return changes for it.","source":{"title":"Use change tracking to synchronize data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-change-tracking-synchronize-data-external-systems"}},{"id":"gen-237","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Using the Organization service, which message do you call to retrieve the set of changes for a change-tracking-enabled table along with a token for the next synchronization?","options":["RetrieveMultipleRequest","ExecuteMultipleRequest","RetrieveEntityChangesRequest","RetrieveAllChangesRequest"],"correct":[2],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"RetrieveEntityChangesRequest returns the changes (new, updated, and deleted rows) for a change-tracking-enabled table and provides a DataToken used to fetch only subsequent changes.","source":{"title":"Use change tracking to synchronize data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-change-tracking-synchronize-data-external-systems"}},{"id":"gen-238","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Your synchronization code stores the DataToken returned by RetrieveEntityChangesRequest. On the next run, how should this token be used?","options":["Discard it and retrieve all rows again to guarantee consistency","Pass it as the DataVersion on the next RetrieveEntityChangesRequest so only changes since that token are returned","Send it as a filter value on the modifiedon column","Use it as the primary key when calling Retrieve"],"correct":[1],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The token is supplied as the DataVersion property on the next RetrieveEntityChangesRequest, so Dataverse returns only the changes that occurred after that token was issued.","source":{"title":"Use change tracking to synchronize data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-change-tracking-synchronize-data-external-systems"}},{"id":"gen-239","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When you retrieve entity changes, how are rows that were deleted since the last token represented so your external system can remove them?","options":["They appear as normal rows with all columns null","They are silently omitted, so you must diff against a full copy","They are returned as RemovedOrDeleted change items containing the deleted row's ID","They raise an exception that must be caught per row"],"correct":[2],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Change tracking returns deleted rows as a distinct RemovedOrDeleted change type carrying the record's ID, so the external system knows which rows to delete rather than having to infer it.","source":{"title":"Use change tracking to synchronize data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-change-tracking-synchronize-data-external-systems"}},{"id":"gen-240","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"With the Dataverse Web API, how do you request only the rows that changed since a prior read of a change-tracking-enabled table?","options":["Add the Prefer: odata.track-changes header, then use the returned @odata.deltaLink on the next request","Append $expand=changes to the query","Send an If-Modified-Since header with yesterday's date","Call the RetrieveEntityChanges function through a bound action"],"correct":[0],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In the Web API you send the Prefer: odata.track-changes header; the response includes an @odata.deltaLink that you use on the next request to retrieve only subsequent changes.","source":{"title":"Use change tracking to synchronize data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-change-tracking-synchronize-data-external-systems"}},{"id":"gen-241","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team plans to store delta tokens and reuse them indefinitely. What limitation should they design for with change tracking tokens?","options":["Tokens are valid only for the user who created them","Tokens can expire, after which a full synchronization must be performed to obtain a new baseline","Tokens must be refreshed every 60 seconds","Tokens work only against activity tables"],"correct":[1],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Delta tokens are not guaranteed to remain valid forever; if a token has expired the request fails and the client must run a full sync to establish a new baseline token.","source":{"title":"Use change tracking to synchronize data — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-change-tracking-synchronize-data-external-systems"}},{"id":"gen-242","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An external ERP system identifies customers by an immutable ERP number, not by the Dataverse GUID. What Dataverse feature lets integration code reference account rows by that ERP number?","options":["A rollup column on the account","A calculated column that concatenates name and number","A many-to-many relationship to a reference table","An alternate key defined on the Account table using the ERP number column"],"correct":[3],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Alternate keys let you define one or more columns (such as an external ERP number) that uniquely identify a row, so integration code can reference records without knowing the Dataverse GUID.","source":{"title":"Work with alternate keys — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/define-alternate-keys-entity"}},{"id":"gen-243","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement about column data types supported in an alternate key definition is correct?","options":["Any column type, including multiline text and file columns, can be part of an alternate key","Only the primary key GUID column can form an alternate key","Alternate keys support types such as whole number, decimal, string, and lookup, but not all column types are allowed","Alternate keys can only use a single string column"],"correct":[2],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Alternate keys can be built from a limited set of column types (for example decimal, whole number, single line of text, datetime, lookup, and choice); many types are not supported, and a key can combine multiple columns.","source":{"title":"Work with alternate keys — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/define-alternate-keys-entity"}},{"id":"gen-244","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After you create an alternate key on a large existing table, why might the key show a status that it is not yet ready for use?","options":["Alternate keys require a solution export before activating","Dataverse creates a supporting index asynchronously and the key becomes active only after that job completes","The key must be manually published from the maker portal each time","Alternate keys only activate after the table is set to elastic"],"correct":[1],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Creating an alternate key triggers a system job that builds the underlying unique index; on tables with existing data the key is not usable until that asynchronous job finishes successfully.","source":{"title":"Work with alternate keys — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/define-alternate-keys-entity"}},{"id":"gen-245","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the Dataverse Web API, which URL correctly retrieves an account by an alternate key named accountnumber with value ABC123?","options":["GET /api/data/v9.2/accounts?$filter=accountnumber eq 'ABC123'","GET /api/data/v9.2/accounts/key/ABC123","GET /api/data/v9.2/accounts(altkey=ABC123)","GET /api/data/v9.2/accounts(accountnumber='ABC123')"],"correct":[3],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Web API supports keyed access using the alternate key column name and value inside the parentheses, e.g. accounts(accountnumber='ABC123'), avoiding a separate lookup of the GUID.","source":{"title":"Work with alternate keys — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/define-alternate-keys-entity"}},{"id":"gen-246","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"What behavior does the unique index behind an alternate key enforce on the table's rows?","options":["It allows duplicate values but flags them for review","It prevents two rows from having the same combination of values in the key's columns","It automatically deletes older rows that share the same key value","It only applies uniqueness to rows created after the key was defined"],"correct":[1],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An alternate key is backed by a unique index, so Dataverse rejects any create or update that would produce a duplicate value combination across the key columns, guaranteeing uniqueness.","source":{"title":"Work with alternate keys — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/define-alternate-keys-entity"}},{"id":"gen-247","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An integration receives records from an external system and must create the row if it does not exist or update it if it does, without first querying to check. Which Dataverse message accomplishes this in a single call?","options":["CreateRequest","UpdateRequest","UpsertRequest","ExecuteTransactionRequest"],"correct":[2],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"UpsertRequest performs a create-or-update in one operation: Dataverse inserts the row if it does not exist or updates it if it does, eliminating a separate existence check.","source":{"title":"Use Upsert to create or update a record — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-upsert-insert-update-record"}},{"id":"gen-248","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"How does an Upsert operation determine whether a matching row already exists so it can decide between insert and update?","options":["It always compares the createdon timestamp","It performs a fuzzy match on the primary name column","It matches only on the modifiedby user","It matches on the row's primary ID or on an alternate key value supplied on the target entity"],"correct":[3],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Upsert locates an existing row using the primary key (GUID) or an alternate key provided on the target; if a match is found it updates, otherwise it creates, which is why alternate keys pair naturally with Upsert for integrations.","source":{"title":"Use Upsert to create or update a record — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-upsert-insert-update-record"}},{"id":"gen-249","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the Web API, which HTTP method and key style is used to perform an upsert of an account identified by the alternate key accountnumber?","options":["POST to /accounts with the accountnumber in the body","PATCH to /accounts(accountnumber='...') with the row's data in the body","PUT to /accounts with an If-Match header of *","GET to /accounts(accountnumber='...') followed by a POST"],"correct":[1],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A PATCH request against a URL that uses the alternate key, e.g. accounts(accountnumber='...'), performs an upsert: it updates the matched row or creates one if none exists.","source":{"title":"Use Upsert to create or update a record — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-upsert-insert-update-record"}},{"id":"gen-250","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"You want a Web API PATCH to update an existing row only, and fail if the row does not exist (preventing an accidental create). Which header enforces this?","options":["If-Match: *","Prefer: return=representation","If-None-Match: *","Prefer: odata.track-changes"],"correct":[0],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Adding If-Match: * to a PATCH tells Dataverse to update only if the row exists and to return an error instead of creating one, which prevents the upsert's create branch.","source":{"title":"Use Upsert to create or update a record — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-upsert-insert-update-record"}},{"id":"gen-251","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After calling UpsertRequest through the Organization service, how can your code tell whether the operation created a new row or updated an existing one?","options":["By inspecting the RecordCreated property on the UpsertResponse","By re-querying the row and comparing createdon to modifiedon","By catching an exception that is only thrown on updates","There is no way to know; the caller must query afterward"],"correct":[0],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"UpsertResponse exposes a RecordCreated boolean that is true when a new row was inserted and false when an existing row was updated, so the caller can branch without re-querying.","source":{"title":"Use Upsert to create or update a record — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-upsert-insert-update-record"}},{"id":"gen-252","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer chooses Upsert with an alternate key over a query-then-create/update pattern for a high-volume import. What is the primary advantage?","options":["It bypasses all plug-ins and business rules on the table","It disables the unique index so duplicates load faster","It guarantees the operation runs asynchronously in the background","It reduces round trips and race conditions by resolving insert-versus-update in a single server operation"],"correct":[3],"skill":6,"sub":"6.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Upsert collapses the existence check and the write into one atomic server-side call, cutting round trips and avoiding the race condition where a row is created between a separate check and write.","source":{"title":"Use Upsert to create or update a record — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-apps/developer/data-platform/use-upsert-insert-update-record"}}];
